function getMissionLibrarySuggested() {
  const all = Object.entries(MISSION_LIBRARY).flatMap(([cat, items]) =>
    items.map(t => ({ ...t, category: cat }))
  );
  const shuffled = all.sort(() => 0.5 - Math.random());
  return shuffled.slice(0, 12);
}

