async function bindAuditPanelBtns(audit) {
  await new Promise(r => setTimeout(r, 60));
  const rerunBtn = document.getElementById('audit-panel-rerun');
  const exportBtn = document.getElementById('audit-panel-export');
  if (rerunBtn) {
    rerunBtn.addEventListener('click', async () => {
      rerunBtn.disabled = true;
      rerunBtn.textContent = 'Audit en cours…';
      try {
        const res = await apiAction('POST', '/api/audits', { url: audit.url });
        if (res) {
          const idx = STATE.audits.findIndex(x => x.id === audit.id);
          if (idx >= 0) STATE.audits.splice(idx, 1);
          STATE.audits.unshift(res);
        }
        showToast('success', `Audit relancé pour ${escHtml(audit.url)}`);
        closeFloatPanel();
        render();
      } catch(e) {
        showToast('error', 'Erreur lors du relancement');
        rerunBtn.disabled = false;
        rerunBtn.textContent = '🔄 Relancer l\'audit';
      }
    });
  }
  if (exportBtn) {
    exportBtn.addEventListener('click', async () => {
      exportBtn.disabled = true;
      exportBtn.textContent = 'Génération…';
      try {
        const host = (audit.url || '').replace(/^https?:\/\//, '').split('/')[0];
        const name = `Audit ${host} — ${new Date().toLocaleDateString('fr-FR')}`;
        const res = await apiAction('POST', '/api/reports', { name, auditId: audit.id, format: 'PDF' });
        const r = res || { id: 'r' + Date.now(), name };
        STATE.reports.unshift(r);
        showToast('success', 'Téléchargement du rapport PDF…');
        downloadReportPdf(r.id, name);
      } catch(e) {
        showToast('error', 'Erreur lors de la génération PDF');
      }
      exportBtn.disabled = false;
      exportBtn.textContent = '⬇ Exporter PDF';
    });
  }
}

