function showFatalError(msg) {
  document.body.innerHTML = `<div style="display:flex;align-items:center;justify-content:center;height:100vh;background:#050810;color:#ef4444;font-family:Inter,sans-serif;text-align:center;padding:32px"><div><div style="font-size:48px;margin-bottom:16px">⚠</div><div style="font-size:18px;font-weight:700;margin-bottom:8px">Connexion au serveur impossible</div><div style="color:#94a3b8;font-size:14px">${escHtml(msg)}</div></div></div>`;
}

async function loadData() {
  let me, overview, audits, monitors, reports, team;
  try {
    [me, overview] = await Promise.all([apiFetch('/api/me'), apiFetch('/api/overview')]);
  } catch (e) {
    if (PREVIEW_MODE) {
      console.warn('[FP] Preview mode: using mock /api/me + /api/overview', e);
      me = null; overview = null;
    } else {
      showFatalError('Impossible de joindre /api/me. Vérifiez que le backend est démarré.');
      return;
    }
  }
  STATE.me = me || (PREVIEW_MODE ? MOCK_ME : null);
  if (!STATE.me) { showFatalError('/api/me n\'a pas répondu.'); return; }

  try {
    [audits, monitors, reports, team] = await Promise.all([
      apiFetch('/api/audits'), apiFetch('/api/monitors'),
      apiFetch('/api/reports'), apiFetch('/api/team'),
    ]);
  } catch (e) {
    if (PREVIEW_MODE) {
      console.warn('[FP] Preview mode: using mock section data', e);
      audits = monitors = reports = team = null;
    } else {
      showFatalError('Impossible de joindre les APIs de section (/api/audits, /api/monitors…).');
      return;
    }
  }

  STATE.audits   = normArr(audits,   'audits')   ?? (PREVIEW_MODE ? MOCK_AUDITS   : []);
  STATE.monitors = normArr(monitors, 'monitors') ?? (PREVIEW_MODE ? MOCK_MONITORS : []);
  STATE.reports  = normArr(reports,  'reports')  ?? (PREVIEW_MODE ? MOCK_REPORTS  : []);
  STATE.team     = normArr(team,     'members')  ?? (PREVIEW_MODE ? MOCK_TEAM     : []);

  try {
    const schedules = await apiFetch('/api/audits/schedule');
    STATE.auditSchedules = Array.isArray(schedules) ? schedules : [];
  } catch(_) { STATE.auditSchedules = []; }
  try {
    const upcoming = await apiFetch('/api/audits/upcoming');
    STATE.auditUpcoming = Array.isArray(upcoming) ? upcoming : [];
  } catch(_) { STATE.auditUpcoming = []; }
  try {
    const alertRules = await apiFetch('/api/alert-rules');
    STATE.alertRules = Array.isArray(alertRules) ? alertRules : [];
  } catch(_) { STATE.alertRules = []; }
  try {
    const alertEvents = await apiFetch('/api/alert-events');
    STATE.alertEvents = Array.isArray(alertEvents) ? alertEvents : [];
  } catch(_) { STATE.alertEvents = []; }
  try {
    const activity = await apiFetch('/api/activity');
    STATE.activityEvents = Array.isArray(activity) ? activity : [];
  } catch(_) { STATE.activityEvents = []; }
  if (!STATE.historySiteUrl && STATE.audits.length > 0) STATE.historySiteUrl = STATE.audits[0].url;

  // Missions — backend avec fallback localStorage puis MOCK
  if (typeof window.FP_MISSIONS_API !== 'undefined') {
    const apiMissions = await window.FP_MISSIONS_API.load();
    STATE.missions = apiMissions
      ?? JSON.parse(localStorage.getItem('fp-missions') || 'null')
      ?? (PREVIEW_MODE ? MOCK_MISSIONS : []);
  } else {
    STATE.missions = JSON.parse(localStorage.getItem('fp-missions') || 'null') ?? (PREVIEW_MODE ? MOCK_MISSIONS : []);
  }

  STATE.calendarEvents = JSON.parse(localStorage.getItem('fp-calendarEvents') || '[]');
  STATE.overview = overview;

  // Keywords — charger depuis API
  if (typeof window.FP_KEYWORDS_API !== 'undefined') {
    const apiKws = await window.FP_KEYWORDS_API.load();
    if (apiKws) STATE.keywords = apiKws;
  }

  // Competitors — charger depuis API
  if (typeof window.FP_COMPETITORS_API !== 'undefined') {
    const apiComps = await window.FP_COMPETITORS_API.load();
    if (apiComps) STATE.competitors = apiComps;
  }

  // Connectors — charger depuis API
  if (typeof window.FP_CONNECTORS_API !== 'undefined') {
    const apiConns = await window.FP_CONNECTORS_API.load();
    if (apiConns) STATE.connectors = apiConns;
  }

  // Notifications — backend activité avec fallback localStorage puis mock
  if (typeof window.FP_NOTIF_API !== 'undefined') {
    const apiNotifs = await window.FP_NOTIF_API.load();
    STATE.notifications = apiNotifs
      ?? JSON.parse(localStorage.getItem('fp-notifs') || 'null')
      ?? [
        { id:'n1', type:'error',   title:'Monitor DOWN',   desc:'restaurant-lesoleil.com', time:'44 min', read:false },
        { id:'n2', type:'success', title:'Audit terminé',  desc:'boulangerie-martin.fr — 82/100', time:'12 min', read:false },
        { id:'n3', type:'info',    title:'Rapport prêt',   desc:'Rapport Mai 2026 généré', time:'2h', read:true },
        { id:'n4', type:'warning', title:'Quota à 29%',    desc:'Audits : 87/300 utilisés', time:'Hier', read:true },
      ];
  } else {
    STATE.notifications = JSON.parse(localStorage.getItem('fp-notifs') || 'null') || [
      { id:'n1', type:'error',   title:'Monitor DOWN',   desc:'restaurant-lesoleil.com', time:'44 min', read:false },
      { id:'n2', type:'success', title:'Audit terminé',  desc:'boulangerie-martin.fr — 82/100', time:'12 min', read:false },
      { id:'n3', type:'info',    title:'Rapport prêt',   desc:'Rapport Mai 2026 généré', time:'2h', read:true },
      { id:'n4', type:'warning', title:'Quota à 29%',    desc:'Audits : 87/300 utilisés', time:'Hier', read:true },
    ];
  }

  // Apply pinned state
  STATE.audits   = STATE.audits.map(a => ({ ...a, pinned: !!(STATE.pinned['audit_'+a.id]) }));
  STATE.monitors = STATE.monitors.map(m => ({ ...m, pinned: !!(STATE.pinned['monitor_'+m.id]) }));

  // Fetch 30-day checks summary for each monitor (best-effort, non-blocking)
  // Re-renders the monitors view when each summary resolves so sparklines appear immediately
  if (STATE.monitors.length > 0) {
    let pendingRender = false;
    const scheduleRender = () => {
      if (pendingRender) return;
      pendingRender = true;
      requestAnimationFrame(() => {
        pendingRender = false;
        if (STATE.route === 'monitors') render();
      });
    };
    Promise.allSettled(
      STATE.monitors.map(m =>
        apiFetch(`/api/monitors/${m.id}/checks-summary`)
          .then(data => { if (Array.isArray(data)) { STATE.monitorsSummary[m.id] = data; scheduleRender(); } })
          .catch(() => {})
      )
    ).catch(() => {});
  }
}

// ─────────────────────────────────────────────────────────────────
// UTILITY FUNCTIONS
// ─────────────────────────────────────────────────────────────────
const $ = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

function scoreColor(s) { return s >= 70 ? '#22c55e' : s >= 40 ? '#f59e0b' : '#ef4444'; }
function scoreLabel(s) { return s >= 70 ? 'Bon' : s >= 40 ? 'Moyen' : 'Critique'; }
function impactColor(i) { return i === 'Très élevé' ? '#ef4444' : i === 'Élevé' ? '#f59e0b' : '#22c55e'; }
function statusBadgeColor(s) { return s === 'up' ? '#22c55e' : s === 'down' ? '#ef4444' : '#f59e0b'; }
function statusLabel(s) { return s === 'up' ? 'UP' : s === 'down' ? 'DOWN' : 'LENT'; }
function relDate(d) { return new Date(d).toLocaleDateString('fr-FR'); }
function sanitizeNotes(raw) { return String(raw).replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim().slice(0,2000); }
function unread() { return STATE.notifications.filter(n => !n.read).length; }
function avgScore() { return STATE.audits.length ? Math.round(STATE.audits.reduce((a,b) => a+b.score, 0) / STATE.audits.length) : 0; }
function monitorsDown() { return STATE.monitors.filter(m => m.status === 'down').length; }
function saveMissions() {
  // Synchrone : mise à jour optimiste du localStorage (cache local)
  localStorage.setItem('fp-missions', JSON.stringify(STATE.missions));
  // Asynchrone : persistance backend (best-effort, non bloquant)
  // Les mutations individuelles (create/update/delete) appellent FP_MISSIONS_API directement.
}
function logActivityEvent(type, label, metadata = {}) {
  fetch('/api/activity', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ type, label, metadata }) }).catch(() => {});
}
function saveCalendarEvents() { localStorage.setItem('fp-calendarEvents', JSON.stringify(STATE.calendarEvents)); }
function saveSettings() { localStorage.setItem('fp-settings', JSON.stringify(STATE.settings)); }
function saveChecklist() { localStorage.setItem('fp-checklist', JSON.stringify(STATE.checklist)); }
function saveNotifs() {
  localStorage.setItem('fp-notifs', JSON.stringify(STATE.notifications));
}

function badge(label, color) {
  return `<span class="fp-badge" style="background:${color}18;border-color:${color}35;color:${color}">${escHtml(String(label))}</span>`;
}

function btn(label, cls, icon = '', attrs = '') {
  return `<button class="fp-btn ${cls}" ${attrs}>${icon ? svgIcon(icon) : ''}${label}</button>`;
}

function applyFreeModules() {
  const m = STATE.freeModules || {};
  document.body.classList.toggle('fp-compact', !!m.compactMode);
  document.body.classList.toggle('fp-focus-mode', !!m.focusMode);
}

