function sparklineSVG(data, color = '#2563EB', w = 80, h = 28) {
  const pad = 2;
  const max = Math.max(...data, 1), min = Math.min(...data, 0);
  const points = data.map((v, i) => {
    const x = pad + (i / (data.length - 1 || 1)) * (w - pad * 2);
    const y = pad + (1 - (v - min) / (max - min || 1)) * (h - pad * 2);
    return { x, y, v };
  });
  const pts = points.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
  const hitR = Math.max(5, Math.round((w / (data.length || 1)) * 0.55));
  const hits = points.map((p, i) =>
    `<circle class="fp-spark-hit" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="${hitR}" fill="transparent" data-score="${p.v}" data-idx="${i}" data-total="${data.length}" data-color="${color}"/>`
  ).join('');
  return `<svg class="fp-sparkline" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" overflow="visible">
    <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
    ${hits}
  </svg>`;
}

// Generate consistent simulated SEO trend data for an audit
// n = number of data points (7 = weekly, 30 = daily)
function seoTrendData(audit, n = 7) {
  const score = audit.score;
  const trend = audit.status === 'ok' ? 1.8 : audit.status === 'error' ? -2.2 : 0.4;
  // Use audit id chars as seed for deterministic noise
  const seed = audit.id.split('').reduce((s, c) => s + c.charCodeAt(0), 0);
  const data = [];
  for (let i = 0; i < n; i++) {
    const noise = Math.sin(seed * 0.3 + i * 1.9) * 2.5 + Math.cos(seed * 0.7 + i * 3.1) * 1.5;
    const val = Math.round(Math.max(5, Math.min(100, score - trend * (n - 1 - i) * 0.7 + noise)));
    data.push(val);
  }
  return data;
}

// Multi-line SVG chart for per-site 30-day trend
let _trendChartNonce = 0;
function seoTrendLineChart(audits, w = 560, h = 160) {
  if (!audits || audits.length === 0) return '';
  const chartId = 'tc' + (++_trendChartNonce);
  const n = 30;
  const padX = 32, padY = 12;
  const innerW = w - padX * 2, innerH = h - padY * 2;
  const allData = audits.map(a => seoTrendData(a, n));
  const allVals = allData.flat();
  const minV = Math.max(0, Math.min(...allVals) - 5);
  const maxV = Math.min(100, Math.max(...allVals) + 5);
  const xi = i => padX + (i / (n - 1)) * innerW;
  const yi = v => padY + (1 - (v - minV) / (maxV - minV || 1)) * innerH;
  const colors = ['#2563EB','#22c55e','#f59e0b','#ef4444','#8b5cf6','#ec4899'];

  // Y axis grid lines
  const gridVals = [minV, Math.round((minV + maxV) / 2), maxV].map(v => Math.round(v));
  let gridLines = gridVals.map(v => `
    <line x1="${padX}" y1="${yi(v)}" x2="${padX + innerW}" y2="${yi(v)}" stroke="rgba(255,255,255,0.06)" stroke-width="1"/>
    <text x="${padX - 4}" y="${yi(v) + 4}" fill="rgba(255,255,255,0.3)" font-size="9" text-anchor="end">${v}</text>
  `).join('');

  // X axis labels: J-30, J-15, J-0
  const xLabels = [
    { i: 0, label: 'J-30' },
    { i: Math.round(n / 2), label: `J-${Math.round(n / 2)}` },
    { i: n - 1, label: "Auj." }
  ].map(({ i, label }) => `<text x="${xi(i)}" y="${padY + innerH + 14}" fill="rgba(255,255,255,0.3)" font-size="9" text-anchor="middle">${label}</text>`).join('');

  // Lines per site
  let lines = '';
  audits.forEach((a, ai) => {
    const color = colors[ai % colors.length];
    const pts = allData[ai].map((v, i) => `${xi(i)},${yi(v)}`).join(' ');
    const domain = a.url.replace(/^https?:\/\//, '').replace(/\/$/, '');
    // Area fill gradient
    const gradId = `${chartId}_g${ai}`;
    // Invisible hit circles and highlight dots for each data point
    const hitCircles = allData[ai].map((v, i) =>
      `<circle class="fp-trend-hit" cx="${xi(i).toFixed(1)}" cy="${yi(v).toFixed(1)}" r="7" fill="transparent" data-site="${escHtml(domain)}" data-score="${v}" data-idx="${i}" data-color="${color}"/>` +
      `<circle class="fp-trend-dot" cx="${xi(i).toFixed(1)}" cy="${yi(v).toFixed(1)}" r="3.5" fill="${color}" stroke="rgba(0,0,0,0.4)" stroke-width="1.5" data-idx="${i}" style="display:none;pointer-events:none"/>`
    ).join('');
    lines += `
      <defs>
        <linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="${color}" stop-opacity="0.18"/>
          <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <polygon points="${xi(0)},${yi(minV)} ${allData[ai].map((v, i) => `${xi(i)},${yi(v)}`).join(' ')} ${xi(n - 1)},${yi(minV)}" fill="url(#${gradId})"/>
      <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" opacity="0.9"/>
      <circle cx="${xi(n - 1)}" cy="${yi(allData[ai][n - 1])}" r="3" fill="${color}" stroke="rgba(0,0,0,0.3)" stroke-width="1"/>
      ${hitCircles}
    `;
  });

  // Legend
  const legend = audits.map((a, ai) => {
    const color = colors[ai % colors.length];
    const domain = a.url.replace(/^https?:\/\//, '').replace(/\/$/, '');
    const lastVal = allData[ai][n - 1];
    const firstVal = allData[ai][0];
    const delta = lastVal - firstVal;
    const sign = delta >= 0 ? '+' : '';
    return `<span style="display:inline-flex;align-items:center;gap:4px;font-size:10px;color:rgba(255,255,255,0.6)">
      <span style="display:inline-block;width:10px;height:2px;background:${color};border-radius:1px"></span>
      ${escHtml(domain)}
      <span style="color:${delta >= 0 ? '#22c55e' : '#ef4444'};font-weight:700">${sign}${delta}pts</span>
    </span>`;
  }).join('');

  return `
    <div class="fp-trend-chart-wrap">
      <svg class="fp-trend-chart-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:${h}px" data-padx="${padX}" data-pady="${padY}" data-innerw="${innerW}" data-innerh="${innerH}" data-n="${n}">
        <line class="fp-xhair-line" x1="0" y1="${padY}" x2="0" y2="${padY + innerH}" stroke="rgba(255,255,255,0.22)" stroke-width="1" stroke-dasharray="4,3" style="display:none;pointer-events:none"/>
        ${gridLines}
        ${xLabels}
        ${lines}
      </svg>
      <div class="fp-trend-chart-legend">${legend}</div>
    </div>
  `;
}

function miniAreaChart(data, color = '#2563EB', w = '100%', h = 100) {
  if (!data || data.length === 0) return '';
  const keys = Object.keys(data[0]).filter(k => k !== 'label' && k !== 'day');
  const colors = ['#2563EB', '#22c55e', '#f59e0b'];
  const allVals = data.flatMap(d => keys.map(k => +d[k] || 0));
  const maxV = Math.max(...allVals, 1);
  const svgW = 460, svgH = 96, padX = 28, padY = 8, labelH = 16;
  const innerW = svgW - padX * 2, innerH = svgH - padY * 2;
  const xi = (i) => padX + (i / (data.length - 1)) * innerW;
  const yi = (v) => padY + (1 - v / maxV) * innerH;

  let paths = '';
  keys.forEach((k, ki) => {
    const pts = data.map((d, i) => `${xi(i)},${yi(+d[k] || 0)}`).join(' ');
    const firstX = xi(0), lastX = xi(data.length - 1);
    paths += `<defs><linearGradient id="g${ki}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="5%" stop-color="${colors[ki]}" stop-opacity="0.3"/>
      <stop offset="95%" stop-color="${colors[ki]}" stop-opacity="0"/>
    </linearGradient></defs>
    <polygon points="${firstX},${svgH} ${pts} ${lastX},${svgH}" fill="url(#g${ki})"/>
    <polyline points="${pts}" fill="none" stroke="${colors[ki]}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>`;
  });

  const labels = data.map((d, i) =>
    `<text x="${xi(i)}" y="${svgH + labelH - 2}" fill="#4b5e8a" font-size="10" text-anchor="middle">${d.day || d.label || ''}</text>`
  ).join('');

  return `<svg viewBox="0 0 ${svgW} ${svgH + labelH}" width="100%" height="${h}" preserveAspectRatio="none">${paths}${labels}</svg>`;
}

// Deterministic pseudo-random (no Math.random) — seed + index → [0,1)
function seededRand(seed, i) {
  const x = Math.sin(seed * 12.9898 + i * 78.233) * 43758.5453;
  return x - Math.floor(x);
}

// Generate 90 deterministic check results for a monitor (90 × 5min = 7.5h)
function monitorCheckHistory(monitor, n = 90) {
  const seed = monitor.id.split('').reduce((s, c) => s + c.charCodeAt(0), 0);
  const downtimeRate = 1 - (monitor.uptime / 100);
  const checks = Array.from({length: n}, (_, i) => seededRand(seed, i) > downtimeRate ? 'up' : 'down');
  if (monitor.status === 'down') { checks[n - 1] = 'down'; checks[n - 2] = 'down'; }
  if (monitor.status === 'up' && checks[n - 1] === 'down') checks[n - 1] = 'up';
  return checks;
}

// Uptime % computed from the deterministic check history
function computeRealUptime(monitor) {
  const checks = monitorCheckHistory(monitor);
  const up = checks.filter(c => c === 'up').length;
  return (up / checks.length * 100).toFixed(1);
}

// 7-point deterministic latency history for monitor sparkline
// Uses check history so down events become 0ms data points
function monitorLatencyData(monitor, n = 7) {
  const seed = monitor.id.split('').reduce((s, c) => s + c.charCodeAt(0), 0) + 100;
  const base = monitor.latency || 150;
  const history = monitorCheckHistory(monitor, n);
  return Array.from({length: n}, (_, i) => {
    if (history[i] === 'down') return 0;
    const r = seededRand(seed, i);
    return Math.max(10, Math.round(base * (0.65 + r * 0.7)));
  });
}

// Sparkline specifically for monitor latency: red dots for 0ms (down) events
function monitorSparklineSVG(data, baseColor = '#2563EB', w = 120, h = 22) {
  const DOWN_COLOR = '#ef4444';
  const pad = 2;
  const maxV = Math.max(...data.filter(v => v > 0), 1);
  const points = data.map((v, i) => {
    const x = pad + (i / (data.length - 1 || 1)) * (w - pad * 2);
    const y = v === 0
      ? h - pad
      : pad + (1 - v / maxV) * (h - pad * 2);
    return { x, y, v };
  });
  const pts = points.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
  const hitR = Math.max(5, Math.round((w / (data.length || 1)) * 0.55));
  const downDots = points.filter(p => p.v === 0).map(p =>
    `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3" fill="${DOWN_COLOR}" stroke="rgba(0,0,0,0.25)" stroke-width="1" pointer-events="none"/>`
  ).join('');
  const hits = points.map((p, i) =>
    `<circle class="fp-spark-hit" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="${hitR}" fill="transparent" data-score="${p.v}" data-idx="${i}" data-total="${data.length}" data-color="${p.v === 0 ? DOWN_COLOR : baseColor}" data-type="latency"/>`
  ).join('');
  return `<svg class="fp-sparkline" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" overflow="visible">
    <polyline points="${pts}" fill="none" stroke="${baseColor}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
    ${downDots}
    ${hits}
  </svg>`;
}

function monitorLatencyChartSVG(monitor) {
  const N = 30;
  const W = 320, H = 120, PL = 36, PR = 8, PT = 12, PB = 18;
  const data = monitorLatencyData(monitor, N);
  const upData = data.filter(v => v > 0);
  const minV = upData.length ? Math.min(...upData) : 0;
  const maxV = upData.length ? Math.max(...upData) : 0;
  const avgV = upData.length ? Math.round(upData.reduce((a, b) => a + b, 0) / upData.length) : 0;
  const iW = W - PL - PR;
  const iH = H - PT - PB;
  const range = maxV - minV || 1;
  function xPos(i) { return PL + (i / (N - 1)) * iW; }
  function yPos(v) { return v === 0 ? PT + iH : PT + (1 - (v - minV) / range) * iH; }
  const color = monitor.status === 'down' ? '#ef4444' : monitor.status === 'warn' ? '#f59e0b' : '#2563EB';
  const colorFill = monitor.status === 'down' ? 'rgba(239,68,68,0.10)' : monitor.status === 'warn' ? 'rgba(245,158,11,0.10)' : 'rgba(37,99,235,0.10)';
  const segments = [];
  let seg = [];
  data.forEach((v, i) => {
    if (v === 0) { if (seg.length) { segments.push(seg); seg = []; } }
    else { seg.push({ x: xPos(i), y: yPos(v), v, i }); }
  });
  if (seg.length) segments.push(seg);
  const linePaths = segments.map(s => {
    if (s.length === 1) return `<circle cx="${s[0].x.toFixed(1)}" cy="${s[0].y.toFixed(1)}" r="2.5" fill="${color}"/>`;
    const d = s.map((p, k) => `${k === 0 ? 'M' : 'L'}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
    const area = d + ` L${s[s.length-1].x.toFixed(1)},${(PT+iH).toFixed(1)} L${s[0].x.toFixed(1)},${(PT+iH).toFixed(1)} Z`;
    return `<path d="${area}" fill="${colorFill}" stroke="none"/>
      <path d="${d}" fill="none" stroke="${color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>`;
  }).join('');
  const downMarkers = data.map((v, i) => {
    if (v !== 0) return '';
    const x = xPos(i).toFixed(1);
    return `<line x1="${x}" y1="${PT}" x2="${x}" y2="${PT+iH}" stroke="#ef4444" stroke-width="1" stroke-dasharray="3,2" opacity="0.45"/>
      <circle cx="${x}" cy="${(PT+iH).toFixed(1)}" r="3.5" fill="#ef4444" stroke="rgba(0,0,0,0.25)" stroke-width="1"/>`;
  }).join('');
  const yAvg = upData.length ? yPos(avgV) : PT + iH;
  const yMax = upData.length ? yPos(maxV) : PT + iH;
  const yMin = upData.length ? yPos(minV) : PT + iH;
  const annotations = upData.length ? `
    <line x1="${PL}" y1="${yAvg.toFixed(1)}" x2="${W-PR}" y2="${yAvg.toFixed(1)}" stroke="#94a3b8" stroke-width="0.75" stroke-dasharray="4,3" opacity="0.5"/>
    <text x="${(PL-3).toFixed(1)}" y="${(yMax+3.5).toFixed(1)}" font-size="7.5" fill="#64748b" text-anchor="end">${maxV}ms</text>
    <text x="${(PL-3).toFixed(1)}" y="${(yMin-2).toFixed(1)}" font-size="7.5" fill="#64748b" text-anchor="end">${minV}ms</text>
    <text x="${(PL-3).toFixed(1)}" y="${(yAvg+3.5).toFixed(1)}" font-size="7.5" fill="#94a3b8" text-anchor="end">${avgV}ms</text>` : '';
  const xTicks = [0, 9, 19, 29].map(i => {
    const lbl = i === 29 ? 'Maint.' : `-${N-1-i}`;
    return `<text x="${xPos(i).toFixed(1)}" y="${(PT+iH+12).toFixed(1)}" font-size="7.5" fill="#475569" text-anchor="${i===0?'start':i===29?'end':'middle'}">${lbl}</text>`;
  }).join('');
  const latMarkers = data.map((v, i) => {
    const x = xPos(i).toFixed(1);
    const y = (v === 0 ? PT + iH : yPos(v)).toFixed(1);
    const c = v === 0 ? '#ef4444' : color;
    return `<circle class="fp-lat-marker" data-idx="${i}" cx="${x}" cy="${y}" r="3.5" fill="${c}" stroke="white" stroke-width="1.5" pointer-events="none" style="display:none"/>`;
  }).join('');
  const latHits = data.map((v, i) => {
    const x = xPos(i).toFixed(1);
    const y = (v === 0 ? PT + iH : yPos(v)).toFixed(1);
    const c = v === 0 ? '#ef4444' : color;
    return `<circle class="fp-lat-hit" cx="${x}" cy="${y}" r="8" fill="transparent" data-v="${v}" data-idx="${i}" data-total="${N}" data-color="${c}" style="cursor:crosshair"/>`;
  }).join('');
  return `<div style="margin-top:16px">
    <div style="font-size:10px;font-weight:700;color:var(--fp-text-muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:6px">Latence — 30 derniers checks</div>
    <svg viewBox="0 0 ${W} ${H}" width="100%" style="display:block;overflow:visible">
      <rect x="${PL}" y="${PT}" width="${iW}" height="${iH}" fill="rgba(255,255,255,0.015)" rx="2"/>
      ${linePaths}${downMarkers}${annotations}${xTicks}${latMarkers}${latHits}
    </svg>
    <div style="display:flex;gap:14px;margin-top:6px">
      ${upData.length ? `
        <span style="font-size:11px;color:var(--fp-text-muted)">Min&nbsp;<b style="color:#22c55e">${minV}ms</b></span>
        <span style="font-size:11px;color:var(--fp-text-muted)">Moy&nbsp;<b style="color:#f1f5ff">${avgV}ms</b></span>
        <span style="font-size:11px;color:var(--fp-text-muted)">Max&nbsp;<b style="color:#f59e0b">${maxV}ms</b></span>
      ` : `<span style="font-size:11px;color:#ef4444;font-weight:600">Aucune réponse — site hors ligne</span>`}
      ${data.filter(v=>v===0).length ? `<span style="font-size:11px;color:#ef4444">${data.filter(v=>v===0).length} timeout${data.filter(v=>v===0).length>1?'s':''}</span>` : ''}
    </div>
  </div>`;
}

function uptimeBars(monitor) {
  const checks = monitorCheckHistory(monitor, 30);
  const seed = monitor.id.split('').reduce((s, c) => s + c.charCodeAt(0), 0) + 200;
  return checks.map((status, i) => {
    const isDown = status === 'down';
    const isSlow = monitor.status === 'warn' && seededRand(seed, i) < 0.15;
    const c = isDown ? '#ef4444' : isSlow ? '#f59e0b' : '#22c55e';
    const opacity = isDown || isSlow ? 1 : 0.4 + seededRand(seed + 1, i) * 0.6;
    return `<div class="fp-uptime-bar" style="background:${c};opacity:${opacity.toFixed(2)}"></div>`;
  }).join('');
}

// 30-day uptime sparkline bar chart using real daily aggregated data
function uptime30SparklineSVG(monitorId) {
  const days = STATE.monitorsSummary[monitorId];
  const W = 120, H = 22, barGap = 1;
  const n = 30;
  const barW = (W - barGap * (n - 1)) / n;

  if (!days || days.length === 0) {
    // Placeholder bars while data is loading
    const bars = Array.from({ length: n }, (_, i) => {
      const x = i * (barW + barGap);
      return `<rect x="${x.toFixed(1)}" y="4" width="${barW.toFixed(1)}" height="${(H - 4).toFixed(1)}" rx="1" fill="rgba(148,163,184,0.18)"/>`;
    }).join('');
    return `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${bars}</svg>`;
  }

  const bars = days.map((d, i) => {
    const x = i * (barW + barGap);
    const ratio = d.total > 0 ? d.ok / d.total : -1;
    let fill, barH, y;
    if (d.total === 0) {
      fill = 'rgba(148,163,184,0.18)';
      barH = H - 4;
      y = 4;
    } else if (ratio >= 0.99) {
      fill = '#22c55e';
      barH = H - 4;
      y = 4;
    } else if (ratio >= 0.90) {
      fill = '#f59e0b';
      barH = Math.max(4, Math.round((ratio) * (H - 4)));
      y = H - barH;
    } else {
      fill = '#ef4444';
      barH = Math.max(4, Math.round(ratio * (H - 4)));
      y = H - barH;
    }
    const pct = d.total > 0 ? (ratio * 100).toFixed(1) + '%' : 'No data';
    return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${barH.toFixed(1)}" rx="1" fill="${fill}"><title>${d.date}: ${pct} (${d.ok}/${d.total})</title></rect>`;
  }).join('');

  return `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="display:block">${bars}</svg>`;
}

// ─────────────────────────────────────────────────────────────────
// TOAST SYSTEM
// ─────────────────────────────────────────────────────────────────
function showToast(type, msg) {
  const id = 't' + Date.now() + Math.random().toString(36).slice(2);
  const icons = {
    success: '<polyline points="20 6 9 17 4 12"/>',
    error: '<line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>',
    warning: '<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>',
    info: '<circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>',
  };
  const icon = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">${icons[type]||icons.info}</svg>`;
  const toast = document.createElement('div');
  toast.className = `fp-toast ${type}`;
  toast.id = id;
  toast.innerHTML = `${icon}<span>${escHtml(String(msg))}</span><button class="fp-toast-close" aria-label="Fermer"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>`;
  toast.querySelector('.fp-toast-close').onclick = () => removeToast(id);
  $('#fp-toast-container').prepend(toast);
  setTimeout(() => removeToast(id), 3500);
}

function removeToast(id) {
  const el = document.getElementById(id);
  if (el) { el.style.animation = 'none'; el.style.opacity = '0'; setTimeout(() => el.remove(), 200); }
}

// ─────────────────────────────────────────────────────────────────
// COMMAND PALETTE
// ─────────────────────────────────────────────────────────────────
const CMD_ITEMS = [
  { cat:'Navigation', label:'Vue d\'ensemble',  icon:'search',   route:'overview',  shortcut:'G O' },
  { cat:'Navigation', label:'Missions SEO',     icon:'activity', route:'missions',  shortcut:'G P' },
  { cat:'Navigation', label:'Audits SEO',       icon:'search',   route:'audits',    shortcut:'G A' },
  { cat:'Navigation', label:'Monitors',         icon:'wifi',     route:'monitors',  shortcut:'G M' },
  { cat:'Navigation', label:'Rapports',         icon:'file',     route:'reports',   shortcut:'G R' },
  { cat:'Navigation', label:'Local SEO',        icon:'pin',      route:'local-seo', shortcut:'G L' },
  { cat:'Navigation', label:'Équipe',           icon:'users',    route:'team',      shortcut:'G T' },
  { cat:'Navigation', label:'Facturation',      icon:'shield',   route:'billing',   shortcut:'G B' },
  { cat:'Navigation', label:'Paramètres',       icon:'filter',   route:'settings',  shortcut:'G S' },
  { cat:'Actions',    label:'Assistant IA',     icon:'bot',      route:'ai',        shortcut:'G I' },
  { cat:'Actions',    label:'Nouvel audit',     icon:'zap',      route:'audits',    shortcut:'' },
  { cat:'Actions',    label:'Nouveau monitor',  icon:'activity', route:'monitors',  shortcut:'' },
  { cat:'Actions',    label:'Nouvelle mission', icon:'rocket',   route:'missions',  shortcut:'' },
  { cat:'Actions',    label:'Exporter CSV',     icon:'download', route:null,        shortcut:'E', fn: () => { openFloatPanel('Exporter les données', renderExportPanel()); setupExportPanel(); } },
];

function openCmdPalette() {
  STATE.cmdOpen = true;
  STATE.cmdQuery = '';
  STATE.cmdSel = 0;
  renderCmdPalette();
  const el = $('#fp-cmd-palette');
  el.removeAttribute('hidden');
  el.setAttribute('aria-expanded', 'true');
  setTimeout(() => $('#fp-cmd-palette .fp-cmd-input')?.focus(), 30);
  // Track search history
  if ($('#fp-search-trigger')) $('#fp-search-trigger').setAttribute('aria-expanded','true');
}

function closeCmdPalette() {
  STATE.cmdOpen = false;
  const el = $('#fp-cmd-palette');
  el.setAttribute('hidden', '');
  el.setAttribute('aria-expanded', 'false');
}

function fuzzyMatch(text, pattern) {
  const t = text.toLowerCase();
  const p = pattern.toLowerCase();
  let pi = 0;
  for (let ti = 0; ti < t.length && pi < p.length; ti++) {
    if (t[ti] === p[pi]) pi++;
  }
  return pi === p.length;
}

function renderCmdPalette() {
  const el = $('#fp-cmd-palette');
  const q = STATE.cmdQuery.toLowerCase();
  const filtered = CMD_ITEMS.filter(i => !q || fuzzyMatch(i.label, q) || i.cat.toLowerCase().startsWith(q));

  // Also search audits, monitors, missions, reports as entities
  const auditMatches = q.length > 2 ? STATE.audits.filter(a => a.url.toLowerCase().includes(q)).slice(0, 3).map(a => ({
    cat: 'Audits', label: a.url, icon: 'search', route: 'audits', shortcut: '',
    fn: () => { navigate('audits'); setTimeout(() => { const audit = STATE.audits.find(x=>x.id===a.id); if(audit) openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit)); },300); }
  })) : [];

  const monitorMatches = q.length > 2 ? STATE.monitors.filter(m =>
    m.name.toLowerCase().includes(q) || m.url.toLowerCase().includes(q)
  ).slice(0, 3).map(m => ({
    cat: 'Monitors', label: m.name + ' — ' + m.url, icon: 'activity', route: null, shortcut: '',
    fn: () => { navigate('monitors'); setTimeout(() => openMonitorPanel(m), 300); }
  })) : [];

  const missionMatches = q.length > 2 ? STATE.missions.filter(m =>
    m.title.toLowerCase().includes(q)
  ).slice(0, 3).map(m => ({
    cat: 'Missions', label: m.title, icon: 'rocket', route: 'missions', shortcut: ''
  })) : [];

  const reportMatches = q.length > 2 ? STATE.reports.filter(r =>
    fuzzyMatch((r.name || ''), q) || fuzzyMatch((r.url || ''), q)
  ).slice(0, 3).map(r => ({
    cat: 'Rapports', label: r.name || r.id, icon: 'file', route: 'reports', shortcut: ''
  })) : [];

  const allItems = [...filtered, ...auditMatches, ...monitorMatches, ...missionMatches, ...reportMatches];
  const cats = [...new Set(allItems.map(i => i.cat))];
  STATE.cmdSel = Math.max(0, Math.min(STATE.cmdSel, allItems.length - 1));

  let html = `<div class="fp-cmd-box">
    <div class="fp-cmd-input-wrap">
      ${svgIcon('search')}
      <input class="fp-cmd-input" type="text" placeholder="Rechercher une section, action, audit…" value="${escHtml(STATE.cmdQuery)}" autocomplete="off"/>
      <kbd class="fp-cmd-esc">Esc</kbd>
    </div>
    <div class="fp-cmd-results">`;

  if (allItems.length === 0) {
    html += `<div class="fp-cmd-empty">Aucun résultat pour « ${escHtml(STATE.cmdQuery)} »</div>`;
  } else {
    let gIdx = 0;
    cats.forEach(cat => {
      html += `<div class="fp-cmd-category">${cat}</div>`;
      allItems.filter(i => i.cat === cat).forEach(item => {
        const sel = gIdx === STATE.cmdSel;
        html += `<div class="fp-cmd-item${sel ? ' selected' : ''}" data-idx="${gIdx}">
          <div class="fp-cmd-item-icon">${svgIcon(item.icon)}</div>
          <span class="fp-cmd-item-label">${highlightMatch(item.label, STATE.cmdQuery)}</span>
          ${item.shortcut ? `<kbd class="fp-cmd-item-shortcut">${item.shortcut}</kbd>` : ''}
          ${svgIcon('x') /* chevron */}
        </div>`;
        gIdx++;
      });
    });
  }

  html += `</div></div>`;

  el.innerHTML = html;

  // Save to search history
  if (STATE.cmdQuery.length > 2) {
    STATE.searchHistory = [STATE.cmdQuery, ...STATE.searchHistory.filter(h => h !== STATE.cmdQuery)].slice(0, 5);
    localStorage.setItem('fp-search-hist', JSON.stringify(STATE.searchHistory));
  }

  // Events
  const input = el.querySelector('.fp-cmd-input');
  input.focus();
  input.addEventListener('input', e => { STATE.cmdQuery = e.target.value; STATE.cmdSel = 0; renderCmdPalette(); });
  input.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown') { e.preventDefault(); STATE.cmdSel = Math.min(STATE.cmdSel + 1, allItems.length - 1); renderCmdPalette(); }
    if (e.key === 'ArrowUp')   { e.preventDefault(); STATE.cmdSel = Math.max(STATE.cmdSel - 1, 0); renderCmdPalette(); }
    if (e.key === 'Enter') { const item = allItems[STATE.cmdSel]; if (item) { execCmdItem(item); } }
    if (e.key === 'Escape') { closeCmdPalette(); }
  });
  // Click-only: hover just highlights, no re-render
  el.querySelectorAll('.fp-cmd-item').forEach((item, i) => {
    item.addEventListener('mouseenter', () => {
      el.querySelectorAll('.fp-cmd-item').forEach(it => it.classList.remove('selected'));
      item.classList.add('selected');
      STATE.cmdSel = i;
    });
    item.addEventListener('click', () => execCmdItem(allItems[i]));
  });
  el.addEventListener('click', e => { if (e.target === el) closeCmdPalette(); });
}

function highlightMatch(text, q) {
  if (!q) return escHtml(text);
  const idx = text.toLowerCase().indexOf(q.toLowerCase());
  if (idx < 0) return escHtml(text);
  return escHtml(text.slice(0, idx)) + `<mark style="background:rgba(37,99,235,0.3);border-radius:2px;color:#fff">${escHtml(text.slice(idx, idx + q.length))}</mark>` + escHtml(text.slice(idx + q.length));
}

function execCmdItem(item) {
  if (item.fn) { item.fn(); }
  else if (item.route) { navigate(item.route); }
  closeCmdPalette();
}

