function setupNewReportPanel() {
  function getNotesInRange() {
    const start = $('#nr-date-start')?.value;
    const end   = $('#nr-date-end')?.value;
    return (STATE.calendarEvents||[]).filter(ev => {
      if (!ev.notes) return false;
      if (start && ev.date < start) return false;
      if (end   && ev.date > end)   return false;
      return true;
    });
  }

  function notesOn()  { return !!$('#nr-notes')?.classList.contains('on'); }
  function wlOn()     { return !!$('#nr-wl')?.classList.contains('on'); }

  function refreshNotesPreview() {
    const preview = $('#nr-notes-preview');
    const list    = $('#nr-notes-list');
    if (!preview || !list) return;
    if (!notesOn()) { preview.style.display = 'none'; return; }
    const events = getNotesInRange();
    if (!events.length) { preview.style.display = 'none'; return; }
    preview.style.display = 'block';
    list.innerHTML = events.map(ev => `
      <div style="border-left:2px solid rgba(139,92,246,0.4);padding-left:8px;margin-bottom:8px">
        <div style="font-weight:600;color:var(--fp-text);font-size:11px">${escHtml(ev.title)}
          <span style="font-weight:400;color:var(--fp-text-muted);margin-left:4px">${relDate(ev.date)}</span>
        </div>
        ${ev.site ? `<div style="font-size:10px;color:var(--fp-text-faint);margin-top:1px">${escHtml(ev.site.replace(/^https?:\/\//,''))}</div>` : ''}
        <div style="margin-top:4px;font-size:11px;color:var(--fp-text-soft);white-space:pre-wrap;line-height:1.5">${escHtml(ev.notes)}</div>
      </div>
    `).join('');
  }

  setTimeout(() => {
    const now = new Date();
    const y = now.getFullYear(), m = String(now.getMonth()+1).padStart(2,'0');
    const lastDay = new Date(now.getFullYear(), now.getMonth()+1, 0).getDate();
    const startEl = $('#nr-date-start');
    const endEl   = $('#nr-date-end');
    if (startEl && !startEl.value) startEl.value = `${y}-${m}-01`;
    if (endEl   && !endEl.value)   endEl.value   = `${y}-${m}-${lastDay}`;

    refreshNotesPreview();

    startEl?.addEventListener('change', refreshNotesPreview);
    endEl?.addEventListener('change', refreshNotesPreview);

    $('#nr-notes')?.addEventListener('click', () => {
      const t = $('#nr-notes');
      if (!t) return;
      const next = !t.classList.contains('on');
      t.classList.toggle('on', next);
      t.setAttribute('aria-pressed', String(next));
      refreshNotesPreview();
    });

    $('#nr-wl')?.addEventListener('click', () => {
      const t = $('#nr-wl');
      if (!t) return;
      const next = !t.classList.contains('on');
      t.classList.toggle('on', next);
      t.setAttribute('aria-pressed', String(next));
    });

    $('#nr-generate')?.addEventListener('click', async () => {
      const name = $('#nr-name')?.value.trim();
      const auditId = $('#nr-audit')?.value;
      const format = document.querySelector('input[name="nr-format"]:checked')?.value || 'PDF';
      if (!name) { showToast('warning','Entrez un nom pour le rapport'); return; }
      if (!auditId) { showToast('warning','Sélectionnez un audit'); return; }
      try {
        const whiteLabel    = wlOn();
        const includeNotes  = notesOn();
        const meetingNotes  = includeNotes ? getNotesInRange() : [];
        const dateStart     = $('#nr-date-start')?.value || '';
        const dateEnd       = $('#nr-date-end')?.value   || '';
        const res = await apiAction('POST', '/api/reports', { name, auditId, format, whiteLabel, meetingNotes, dateStart, dateEnd });
        const r = res || { id:'r'+Date.now(), name, type: format, date: new Date().toISOString(), pages: Math.floor(Math.random()*10)+4, shared: false };
        STATE.reports.unshift(r);

        if (format === 'PDF' && r.id) {
          showToast('success', `Téléchargement du rapport PDF « ${escHtml(name)} »…`);
          const link = document.createElement('a');
          link.href = `/api/reports/${r.id}/download`;
          link.download = `${name}.pdf`;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        } else {
          const notesSuffix = meetingNotes.length ? ` · ${meetingNotes.length} note${meetingNotes.length>1?'s':''} de réunion incluse${meetingNotes.length>1?'s':''}` : '';
          showToast('success', `Rapport ${format} « ${escHtml(name)} » généré${notesSuffix}.`);
        }

        closeFloatPanel();
        if (STATE.route === 'reports') render();
      } catch(e) { showToast('error','Erreur lors de la génération du rapport'); }
    });
  }, 50);
}

