async function loadHistoryForUrl(url) {
  if (!url) return;
  if (STATE.auditHistory[url] !== undefined) return; // already cached (including empty [])
  try {
    const data = await apiFetch(`/api/audits/history?url=${encodeURIComponent(url)}&days=90`);
    STATE.auditHistory[url] = Array.isArray(data) ? data : []; // cache even empty
    render();
  } catch(e) {
    console.warn('[FP] loadHistoryForUrl error:', e);
    // Don't cache on error — allow retry
  }
}

function navigate(route) {
  STATE.route = route;
  STATE.subRoute = null;
  try { history.replaceState(null, '', '#' + route); } catch(e) { /* sandboxed */ }
  document.querySelectorAll('.fp-chart-tooltip').forEach(t => t.remove());
  render();
}

function navigateSub(sub) {
  STATE.subRoute = sub;
  render();
}

function renderSubNav(items) {
  return `<nav class="fp-sub-nav" role="tablist">${items.map(t => `
    <button class="fp-sub-nav-item${(STATE.subRoute === t.id) ? ' active' : ''}"
      data-sub-route="${t.id ?? ''}"
      role="tab" aria-selected="${STATE.subRoute === t.id}">${escHtml(t.label)}</button>
  `).join('')}</nav>`;
}

function aiBlock(text, chips = []) {
  return `<div class="fp-ai-block">
    <div class="fp-ai-block-icon">
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2"><path d="M12 2a2 2 0 0 1 2 2c0 .74-.4 1.39-1 1.73V7h1a7 7 0 0 1 7 7h1a1 1 0 0 1 0 2h-1v1a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-1H2a1 1 0 0 1 0-2h1a7 7 0 0 1 7-7h1V5.73c-.6-.34-1-.99-1-1.73a2 2 0 0 1 2-2z"/><circle cx="9" cy="14" r="1"/><circle cx="15" cy="14" r="1"/></svg>
    </div>
    <div class="fp-ai-block-content">
      <div class="fp-ai-block-label">Analyse IA · Flowpoint</div>
      <div class="fp-ai-block-text">${text}</div>
      ${chips.length ? `<div class="fp-ai-block-actions">${chips.map(c=>`<button class="fp-ai-chip" onclick="navigate('ai');setTimeout(()=>{const inp=document.getElementById('fp-ai-input');if(inp){inp.value=${JSON.stringify(c)};inp.dispatchEvent(new Event('input'));}},120)">${escHtml(c)}</button>`).join('')}</div>` : ''}
    </div>
  </div>`;
}

function statCard(label, value, delta, dir = 'up', sub = '') {
  const arrow = dir === 'up' ? '↑' : dir === 'down' ? '↓' : '→';
  return `<div class="fp-stat-card">
    <div class="fp-stat-card-label">${escHtml(label)}</div>
    <div class="fp-stat-card-value">${escHtml(String(value))}</div>
    <div class="fp-stat-card-delta ${dir}">${arrow} ${escHtml(String(delta))}</div>
    ${sub ? `<div style="font-size:11px;color:var(--fp-text-faint);margin-top:2px">${escHtml(sub)}</div>` : ''}
  </div>`;
}

// ── PLAN SWITCHER ─────────────────────────────────────────────────────
function fpToggleIssue(rid, el) {
  STATE.resolvedIssues = STATE.resolvedIssues || {};
  const ok = el.checked;
  if (ok) STATE.resolvedIssues[rid] = true; else delete STATE.resolvedIssues[rid];
  const card = document.querySelector(`[data-issue-rid="${rid}"]`);
  if (card) {
    card.style.opacity = ok ? '0.5' : '1';
    const lbl = card.querySelector('[data-issue-label]');
    if (lbl) lbl.style.textDecoration = ok ? 'line-through' : '';
  }
  showToast(ok ? 'success' : 'info', ok ? 'Issue marquée résolue ✓' : 'Issue réouverte');
}

const FP_PLAN_LIMITS = {
  Starter: { audit: 50,  monitor: 5,   pdf: 50  },
  Pro:     { audit: 300, monitor: 50,  pdf: 300 },
  Agency:  { audit: 999, monitor: 200, pdf: 999 },
};

function changePlan(newPlan) {
  if (!FP_PLAN_LIMITS[newPlan]) return;
  if (!STATE.me) STATE.me = {};
  STATE.me.plan = newPlan;
  const l = FP_PLAN_LIMITS[newPlan];
  STATE.me.usage = STATE.me.usage || {};
  STATE.me.usage.audit   = { used: STATE.me.usage.audit?.used   ?? 87, limit: l.audit   };
  STATE.me.usage.monitor = { used: STATE.me.usage.monitor?.used ?? 18, limit: l.monitor };
  STATE.me.usage.pdf     = { used: STATE.me.usage.pdf?.used     ?? 34, limit: l.pdf     };
  document.getElementById('fp-plan-switcher-dd')?.remove();
  render();
  showToast('success', `Plan → ${newPlan}`);
}

function togglePlanDropdown() {
  if (document.getElementById('fp-plan-switcher-dd')) {
    document.getElementById('fp-plan-switcher-dd').remove(); return;
  }
  const cur = STATE.me?.plan || 'Pro';
  const plans = [
    { n:'Starter', p:'29€/mois',  color:'#94a3b8', desc:'50 audits · 5 monitors' },
    { n:'Pro',     p:'79€/mois',  color:'#2563EB', desc:'300 audits · IA Insights · PDF' },
    { n:'Agency',  p:'199€/mois', color:'#8b5cf6', desc:'Illimité · Tout débridé · API' },
  ];
  const sw = document.getElementById('fp-plan-switcher');
  if (!sw) return;
  const dd = document.createElement('div');
  dd.id = 'fp-plan-switcher-dd';
  dd.className = 'fp-plan-dropdown';
  dd.innerHTML = `
    <div style="padding:8px 14px 7px;font-size:10px;color:var(--fp-text-faint);text-transform:uppercase;letter-spacing:.1em;border-bottom:1px solid var(--fp-border)">Changer de plan (démo)</div>
    ${plans.map(p=>`
      <div class="fp-plan-dropdown-item${p.n===cur?' active':''}" onclick="changePlan('${p.n}')">
        <div class="fp-plan-di-left">
          <div class="fp-plan-di-dot" style="background:${p.color}"></div>
          <div>
            <div class="fp-plan-di-name">${p.n}</div>
            <div style="font-size:10px;color:var(--fp-text-faint)">${p.desc}</div>
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          <span class="fp-plan-di-price">${p.p}</span>
          ${p.n===cur?'<span class="fp-plan-di-check">✓</span>':''}
        </div>
      </div>
    `).join('')}
  `;
  sw.appendChild(dd);
  setTimeout(() => document.addEventListener('click', function _h(e) {
    if (!e.target.closest('#fp-plan-switcher')) {
      document.getElementById('fp-plan-switcher-dd')?.remove();
      document.removeEventListener('click', _h);
    }
  }), 50);
}

function updatePlanSwitcher() {
  const el = document.getElementById('fp-plan-switcher');
  if (!el) return;
  const plan = STATE.me?.plan || 'Pro';
  const colors = { Starter:'#94a3b8', Pro:'#2563EB', Agency:'#8b5cf6' };
  el.innerHTML = `<button class="fp-plan-pill" onclick="togglePlanDropdown()" title="Changer de plan (démo)">
    <div class="fp-ps-dot" style="background:${colors[plan]||'#2563EB'}"></div>
    <span>${plan}</span>
    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"/></svg>
  </button>`;
}

function render() {
  const page = $('#fp-page');
  if (!page) return;

  // Update nav active — match primary route
  $$('.fp-nav-item, .fp-nav-ai').forEach(el => {
    el.classList.toggle('active', el.dataset.route === STATE.route);
  });

  // Update topbar breadcrumb
  const pageNameEl = $('#fp-topbar-page-name');
  if (pageNameEl) pageNameEl.textContent = PAGE_NAMES[STATE.route] || 'Dashboard';

  let html = '';
  switch(STATE.route) {
    case 'overview':       html = renderOverview(); break;
    case 'missions':       html = renderMissions(); break;
    case 'audits':         html = renderAudits(); break;
    case 'monitors':       html = renderMonitors(); break;
    case 'reports':        html = renderReports(); break;
    case 'local-seo':      html = renderLocalSEO(); break;
    case 'team':           html = renderTeam(); break;
    case 'billing':        html = renderBilling(); break;
    case 'settings':       html = renderSettings(); break;
    case 'ai':             html = renderAI(); break;
    case 'growth':         html = renderGrowth(); break;
    case 'competitor':     html = renderCompetitor(); break;
    case 'conversion':     html = renderConversion(); break;
    case 'alerts-center':  html = renderAlertsCenter(); break;
    case 'activity-feed':  html = renderActivityFeed(); break;
    case 'data-explorer':  html = renderDataExplorer(); break;
    case 'client-mode':    html = renderClientMode(); break;
    default:               html = renderOverview();
  }

  page.innerHTML = `<div class="fp-page-animated">${html}</div>`;
  requestAnimationFrame(() => initPageAnimations(STATE.route, STATE.subRoute));

  // Inject sub-nav after section header if route has sub-pages
  const subItems = SUB_NAVS[STATE.route];
  if (subItems) {
    const animated = page.querySelector('.fp-page-animated');
    const sectionHeader = animated?.querySelector('.fp-section-header');
    const subNavHtml = renderSubNav(subItems);
    if (sectionHeader) {
      sectionHeader.insertAdjacentHTML('afterend', subNavHtml);
    } else if (animated) {
      animated.insertAdjacentHTML('afterbegin', subNavHtml);
    }
    // If sub-route active, replace body content after sub-nav
    if (STATE.subRoute !== null) {
      const subContent = renderSubPageContent(STATE.route, STATE.subRoute);
      if (subContent) {
        const subNav = animated?.querySelector('.fp-sub-nav');
        if (subNav) {
          let next = subNav.nextElementSibling;
          while (next) { const r = next; next = next.nextElementSibling; r.remove(); }
          subNav.insertAdjacentHTML('afterend', subContent);
        }
      }
    }

    // Bind sub-nav clicks
    animated?.querySelectorAll('.fp-sub-nav-item').forEach(btn => {
      btn.addEventListener('click', () => {
        const sub = btn.dataset.subRoute || null;
        navigateSub(sub === '' ? null : sub);
      });
    });
  }

  // Bind section-specific events
  bindSectionEvents();
  bindNewRouteEvents();
  syncBulkBar();
  closeFAB();
  closeCtxMenu();
  updatePlanSwitcher();
}

// ─────────────────────────────────────────────────────────────────
// BULK ACTION BAR
// ─────────────────────────────────────────────────────────────────
function syncBulkBar() {
  let bar = document.getElementById('fp-bulk-bar');
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'fp-bulk-bar';
    bar.className = 'fp-bulk-bar';
    document.body.appendChild(bar);
  }

  const route = STATE.route;
  const selAudits = STATE.selectedAudits.size;
  const selMonitors = STATE.selectedMonitors.size;
  const total = route === 'audits' ? selAudits : route === 'monitors' ? selMonitors : 0;

  if (total === 0) {
    bar.classList.remove('fp-bulk-visible');
    return;
  }

  const label = `${total} sélectionné${total > 1 ? 's' : ''}`;

  if (route === 'audits') {
    bar.innerHTML = `
      <span class="fp-bulk-count">${label}</span>
      <span class="fp-bulk-sep"></span>
      <button class="fp-btn fp-btn-ghost fp-btn-sm" id="bulk-export-csv">${svgIcon('download')} CSV</button>
      <button class="fp-btn fp-btn-ghost fp-btn-sm" id="bulk-rerun">${svgIcon('refresh')} Relancer</button>
      <button class="fp-btn fp-btn-ghost fp-btn-sm" id="bulk-archive" style="color:var(--fp-warning)">${svgIcon('archive')} Archiver</button>
      <button class="fp-btn fp-btn-danger fp-btn-sm" id="bulk-delete-audits">${svgIcon('trash')} Supprimer</button>
      <span style="margin-left:auto"></span>
      <div class="fp-bulk-progress-wrap" id="bulk-progress-wrap" style="display:none">
        <div class="fp-bulk-progress"><div class="fp-bulk-progress-fill" id="bulk-progress-fill" style="width:0%"></div></div>
        <span id="bulk-progress-label" style="font-size:11px;color:var(--fp-text-muted)"></span>
      </div>
      <button class="fp-btn fp-btn-ghost fp-btn-sm" id="bulk-deselect" style="color:var(--fp-text-muted)">✕ Désélectionner</button>
    `;
  } else if (route === 'monitors') {
    bar.innerHTML = `
      <span class="fp-bulk-count">${label}</span>
      <span class="fp-bulk-sep"></span>
      <button class="fp-btn fp-btn-ghost fp-btn-sm" id="bulk-test-monitors">${svgIcon('refresh')} Tester tout</button>
      <button class="fp-btn fp-btn-danger fp-btn-sm" id="bulk-delete-monitors">${svgIcon('trash')} Supprimer</button>
      <span style="margin-left:auto"></span>
      <div class="fp-bulk-progress-wrap" id="bulk-progress-wrap" style="display:none">
        <div class="fp-bulk-progress"><div class="fp-bulk-progress-fill" id="bulk-progress-fill" style="width:0%"></div></div>
        <span id="bulk-progress-label" style="font-size:11px;color:var(--fp-text-muted)"></span>
      </div>
      <button class="fp-btn fp-btn-ghost fp-btn-sm" id="bulk-deselect" style="color:var(--fp-text-muted)">✕ Désélectionner</button>
    `;
  }

  bar.classList.add('fp-bulk-visible');
  bindBulkBarEvents();
}

function bindBulkBarEvents() {
  // Helpers
  const getProgressEls = () => ({
    wrap:  document.getElementById('bulk-progress-wrap'),
    fill:  document.getElementById('bulk-progress-fill'),
    label: document.getElementById('bulk-progress-label'),
  });
  const showProgress = (done, total) => {
    const { wrap, fill, label } = getProgressEls();
    if (wrap) wrap.style.display = 'flex';
    if (fill) fill.style.width = Math.round((done / total) * 100) + '%';
    if (label) label.textContent = `${done}/${total}`;
  };
  const resultToast = (ok, fail, verb, unit) => {
    if (fail === 0) {
      showToast('success', `${ok} ${unit}${ok>1?'s':''} ${verb}${ok>1?'s':''}`);
    } else if (ok === 0) {
      showToast('error', `Échec pour ${fail} ${unit}${fail>1?'s':''}`);
    } else {
      showToast('warning', `${ok} réussi${ok>1?'s':''}, ${fail} échoué${fail>1?'s':''}`);
    }
  };

  // ── Désélectionner — section courante uniquement ──
  document.getElementById('bulk-deselect')?.addEventListener('click', () => {
    if (STATE.route === 'audits') STATE.selectedAudits.clear();
    else if (STATE.route === 'monitors') STATE.selectedMonitors.clear();
    render();
  });

  // ── AUDITS ──
  document.getElementById('bulk-export-csv')?.addEventListener('click', () => {
    const audits = STATE.audits.filter(a => STATE.selectedAudits.has(a.id));
    if (!audits.length) return;
    const header = 'URL,Score SEO,Vitesse,Statut,Date';
    const rows = audits.map(a =>
      `"${a.url}",${a.score},${a.speed},"${a.score>=70?'Bon':a.score>=45?'Moyen':'Mauvais'}","${new Date(a.date).toLocaleDateString('fr-FR')}"`
    );
    const csv = [header, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `audits-flowpoint-${new Date().toISOString().slice(0,10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    showToast('success', `CSV exporté — ${audits.length} audit${audits.length>1?'s':''}`);
  });

  document.getElementById('bulk-rerun')?.addEventListener('click', async () => {
    const ids = [...STATE.selectedAudits];
    const audits = STATE.audits.filter(a => ids.includes(a.id));
    if (!audits.length) return;
    showProgress(0, audits.length);
    showToast('info', `Relance de ${audits.length} audit${audits.length>1?'s':''} en cours…`);
    let done = 0, ok = 0, fail = 0;
    await Promise.allSettled(audits.map(async a => {
      try {
        const res = await apiAction('POST', '/api/audits', { url: a.url });
        if (res) {
          const idx = STATE.audits.findIndex(x => x.id === a.id);
          if (idx >= 0) STATE.audits.splice(idx, 1);
          STATE.audits.unshift(res);
        }
        ok++;
      } catch(e) { fail++; }
      showProgress(++done, audits.length);
    }));
    STATE.selectedAudits.clear();
    resultToast(ok, fail, 'relancé', 'audit');
    render();
  });

  document.getElementById('bulk-archive')?.addEventListener('click', () => {
    const ids = [...STATE.selectedAudits];
    if (!ids.length) return;
    ids.forEach(id => {
      const a = STATE.audits.find(x => x.id === id);
      if (a) a.archived = true;
    });
    STATE.selectedAudits.clear();
    STATE.auditShowArchived = false;
    showToast('info', `${ids.length} audit${ids.length>1?'s':''} archivé${ids.length>1?'s':''} — masqué${ids.length>1?'s':''} de la vue principale`);
    render();
  });

  document.getElementById('bulk-delete-audits')?.addEventListener('click', async () => {
    const ids = [...STATE.selectedAudits];
    if (!ids.length) return;
    if (!confirm(`Supprimer ${ids.length} audit${ids.length>1?'s':''} ? Cette action est irréversible.`)) return;
    showProgress(0, ids.length);
    let done = 0, ok = 0, fail = 0;
    await Promise.allSettled(ids.map(async id => {
      try {
        await apiAction('DELETE', `/api/audits/${id}`);
        STATE.audits = STATE.audits.filter(a => a.id !== id);
        ok++;
      } catch(e) {
        STATE.audits = STATE.audits.filter(a => a.id !== id);
        ok++;
      }
      showProgress(++done, ids.length);
    }));
    STATE.selectedAudits.clear();
    resultToast(ok, fail, 'supprimé', 'audit');
    render();
  });

  // ── MONITORS ──
  document.getElementById('bulk-test-monitors')?.addEventListener('click', async () => {
    const ids = [...STATE.selectedMonitors];
    const monitors = STATE.monitors.filter(m => ids.includes(m.id));
    if (!monitors.length) return;
    showProgress(0, monitors.length);
    showToast('info', `Test de ${monitors.length} monitor${monitors.length>1?'s':''} en cours…`);
    let done = 0, ok = 0, fail = 0;
    await Promise.allSettled(monitors.map(async m => {
      try { await apiAction('POST', `/api/monitors/${m.id}/check`); ok++; }
      catch(e) { fail++; }
      showProgress(++done, monitors.length);
    }));
    STATE.selectedMonitors.clear();
    resultToast(ok, fail, 'testé', 'monitor');
    render();
  });

  document.getElementById('bulk-delete-monitors')?.addEventListener('click', async () => {
    const ids = [...STATE.selectedMonitors];
    if (!ids.length) return;
    if (!confirm(`Supprimer ${ids.length} monitor${ids.length>1?'s':''} ? Cette action est irréversible.`)) return;
    showProgress(0, ids.length);
    let done = 0, ok = 0, fail = 0;
    await Promise.allSettled(ids.map(async id => {
      try {
        await apiAction('DELETE', `/api/monitors/${id}`);
        STATE.monitors = STATE.monitors.filter(m => m.id !== id);
        ok++;
      } catch(e) {
        STATE.monitors = STATE.monitors.filter(m => m.id !== id);
        ok++;
      }
      showProgress(++done, ids.length);
    }));
    STATE.selectedMonitors.clear();
    resultToast(ok, fail, 'supprimé', 'monitor');
    render();
  });
}

// ─────────────────────────────────────────────────────────────────
// EVENT BINDING (per section)
// ─────────────────────────────────────────────────────────────────
function bindSectionEvents() {
  const route = STATE.route;

  // Universal: route buttons
  $$('[data-route]', $('#fp-page')).forEach(el => {
    el.addEventListener('click', () => navigate(el.dataset.route));
  });

  // Universal: hover toolbars btn text
  $$('.quick-win-btn').forEach(btn => btn.addEventListener('click', async () => {
    const label = btn.dataset.label || btn.closest('[data-win-label]')?.dataset.winLabel || btn.textContent?.trim() || 'Quick Win';
    const m = { id:'ms'+Date.now(), title: 'Quick Win : ' + label.slice(0,80), category:'Audits', impact:'Élevé', status:'todo', date: new Date(Date.now()+7*86400000).toISOString().slice(0,10), steps:[] };
    STATE.missions.push(m);
    saveMissions();
    showToast('success','Mission créée depuis Quick Win !');
    if (typeof window.FP_MISSIONS_API !== 'undefined') {
      window.FP_MISSIONS_API.create(m).catch(() => {});
    }
  }));

  if (route === 'overview') {
    $$('[data-audit-pinned]').forEach(btn => btn.addEventListener('click', () => {
      const audit = STATE.audits.find(a => a.id === btn.dataset.auditPinned);
      if (audit) { navigate('audits'); setTimeout(() => { openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit)); bindAuditPanelBtns(audit); },300); }
    }));
    $$('[data-monitor-pinned]').forEach(btn => btn.addEventListener('click', () => {
      const monitor = STATE.monitors.find(m => m.id === btn.dataset.monitorPinned);
      if (monitor) openMonitorPanel(monitor);
    }));
    $('#activity-see-all')?.addEventListener('click', () => openFloatPanel('Historique complet', ACTIVITY_FEED.map(item => {
      const colors = {success:'#22c55e',error:'#ef4444',info:'#2563EB',warning:'#f59e0b',purple:'#8b5cf6'};
      const c = colors[item.type]||'#2563EB';
      return `<div style="display:flex;gap:10px;padding:12px;background:rgba(255,255,255,0.03);border-radius:10px;margin-bottom:8px">
        <div style="width:32px;height:32px;border-radius:10px;background:${c}18;display:flex;align-items:center;justify-content:center">${svgIcon(item.icon).replace('stroke="currentColor"',`stroke="${c}"`)}</div>
        <div><div style="font-size:13px;font-weight:600;color:var(--fp-text)">${item.title}</div><div style="font-size:12px;color:var(--fp-text-muted)">${item.desc}</div><div style="font-size:10px;color:var(--fp-text-faint);margin-top:4px">Il y a ${item.time}</div></div>
      </div>`;
    }).join('')));
    $('#refresh-btn')?.addEventListener('click', () => showToast('success','Données actualisées'));
    $('#export-btn')?.addEventListener('click', () => { openFloatPanel('Exporter les données', renderExportPanel()); setupExportPanel(); });
    $('#mission-tomorrow')?.addEventListener('click', () => {
      const tomorrow = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
      const urgent = STATE.missions.find(m => m.status === 'todo' && m.impact === 'Élevé');
      const target = urgent || STATE.missions.find(m => m.status === 'todo');
      if (target) { target.date = tomorrow; saveMissions(); showToast('success', `Mission reportée à demain (${tomorrow})`); render(); }
      else showToast('warning', 'Aucune mission à reporter');
    });
    $$('#chart-range-toggle .fp-view-toggle-btn').forEach(b => b.addEventListener('click', function() {
      $$('#chart-range-toggle .fp-view-toggle-btn').forEach(x => x.classList.remove('active'));
      this.classList.add('active');
      showToast('info',`Données sur ${this.dataset.range} jours`);
    }));
  }

  if (route === 'audits') {
    $('#audit-search')?.addEventListener('input', e => { STATE.auditFilter = e.target.value; render(); });
    $('#audit-sort')?.addEventListener('change', e => { STATE.auditSort = e.target.value; render(); });
    $$('[data-audit-status-filter]').forEach(b => b.addEventListener('click', () => { STATE.auditStatusFilter = b.dataset.auditStatusFilter; STATE.auditShowArchived = false; render(); }));
    $('#audit-show-archived')?.addEventListener('click', () => { STATE.auditShowArchived = !STATE.auditShowArchived; STATE.auditStatusFilter = 'all'; render(); });
    $('#audit-export-csv')?.addEventListener('click', () => {
      const q = STATE.auditFilter || '';
      const scoreStatus = a => a.score >= 70 ? 'good' : a.score >= 45 ? 'medium' : 'bad';
      const visible = STATE.audits.filter(a =>
        !a.archived &&
        (!q || a.url.includes(q)) &&
        (STATE.auditStatusFilter === 'all' || scoreStatus(a) === STATE.auditStatusFilter)
      );
      exportAuditsCsv(visible);
    });

    // ── Bulk select ──
    const allVisibleIds = () => {
      const q = STATE.auditFilter;
      const scoreStatus = a => a.score >= 70 ? 'good' : a.score >= 45 ? 'medium' : 'bad';
      return STATE.audits
        .filter(a => (!q || a.url.includes(q)) && (STATE.auditStatusFilter === 'all' || scoreStatus(a) === STATE.auditStatusFilter))
        .map(a => a.id);
    };
    const updateSelectAll = () => {
      const cb = $('#audit-select-all');
      if (!cb) return;
      const visible = allVisibleIds();
      const allChecked = visible.length > 0 && visible.every(id => STATE.selectedAudits.has(id));
      cb.checked = allChecked;
      cb.indeterminate = !allChecked && visible.some(id => STATE.selectedAudits.has(id));
    };
    updateSelectAll();
    $('#audit-select-all')?.addEventListener('change', e => {
      const ids = allVisibleIds();
      if (e.target.checked) { ids.forEach(id => STATE.selectedAudits.add(id)); }
      else { ids.forEach(id => STATE.selectedAudits.delete(id)); }
      syncBulkBar();
      $$('.fp-audit-row-cb').forEach(cb => {
        cb.checked = STATE.selectedAudits.has(cb.dataset.id);
        cb.closest('tr')?.classList.toggle('fp-row-sel', STATE.selectedAudits.has(cb.dataset.id));
      });
    });
    $$('.fp-audit-row-cb').forEach(cb => {
      cb.addEventListener('change', e => {
        e.stopPropagation();
        const id = cb.dataset.id;
        if (e.target.checked) { STATE.selectedAudits.add(id); }
        else { STATE.selectedAudits.delete(id); }
        cb.closest('tr')?.classList.toggle('fp-row-sel', STATE.selectedAudits.has(id));
        updateSelectAll();
        syncBulkBar();
      });
      cb.addEventListener('click', e => e.stopPropagation());
    });
    $('#audit-new-btn')?.addEventListener('click', () => { $('#audit-url-input')?.focus(); showToast('info','Entrez l\'URL à auditer'); });
    $('#audit-run-btn')?.addEventListener('click', async () => {
      const url = $('#audit-url-input')?.value.trim();
      if (!url) { showToast('warning','Entrez une URL'); return; }
      try {
        const res = await apiAction('POST', '/api/audits', { url });
        const a = res || { id:'a'+Date.now(), url, score:Math.floor(Math.random()*40)+40, status:'warn', speed:Math.floor(Math.random()*30)+55, date:new Date().toISOString(), issues:Math.floor(Math.random()*15)+1 };
        STATE.audits.unshift(a);
        showToast('success', `Audit lancé pour ${escHtml(url)}`);
        $('#audit-url-input').value = '';
        render();
      } catch(e) { showToast('error','Erreur lors du lancement de l\'audit'); }
    });
    $('#audit-url-input')?.addEventListener('keydown', e => { if(e.key==='Enter') $('#audit-run-btn')?.click(); });

    // Schedule toggles
    $$('.fp-sched-toggle').forEach(chk => {
      chk.addEventListener('change', async () => {
        const url = chk.dataset.url;
        if (!url) return;
        const freqSel = document.querySelector(`.fp-sched-freq[data-url="${CSS.escape(url)}"]`);
        if (chk.checked) {
          if (freqSel) freqSel.disabled = false;
          const freq = freqSel?.value || 'weekly';
          try {
            const sched = await apiAction('POST', '/api/audits/schedule', { url, frequency: freq });
            if (sched && !STATE.auditSchedules.find(s => s.url === url)) STATE.auditSchedules.push(sched);
            showToast('success', `Audit ${freq === 'daily' ? 'quotidien' : freq === 'weekly' ? 'hebdo' : 'mensuel'} activé`);
          } catch(_) {
            const mock = { id:'sched_'+Date.now(), url, frequency: freq, nextRun:Date.now()+7*86400000, createdAt:Date.now() };
            STATE.auditSchedules.push(mock);
            showToast('success', `Audit ${freq === 'daily' ? 'quotidien' : freq === 'weekly' ? 'hebdo' : 'mensuel'} activé`);
          }
          render();
        } else {
          if (freqSel) freqSel.disabled = true;
          const existing = STATE.auditSchedules.find(s => s.url === url);
          if (existing) {
            try { await apiAction('DELETE', `/api/audits/schedule/${existing.id}`); } catch(_) {}
            STATE.auditSchedules = STATE.auditSchedules.filter(s => s.url !== url);
          }
          showToast('info', 'Audit planifié désactivé');
          render();
        }
      });
    });
    $$('.fp-sched-freq').forEach(sel => {
      sel.addEventListener('change', async () => {
        const url = sel.dataset.url;
        if (!url) return;
        const existing = STATE.auditSchedules.find(s => s.url === url);
        if (!existing) return;
        try {
          const updated = await apiAction('PATCH', `/api/audits/schedule/${existing.id}`, { frequency: sel.value });
          Object.assign(existing, updated || { frequency: sel.value });
          showToast('success', `Fréquence mise à jour : ${sel.options[sel.selectedIndex].text}`);
        } catch(_) {
          existing.frequency = sel.value;
          showToast('success', `Fréquence mise à jour : ${sel.options[sel.selectedIndex].text}`);
        }
      });
    });

    // Audit table actions
    $$('.audit-view').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      const audit = STATE.audits.find(a => a.id === btn.dataset.id);
      if (!audit) return;
      openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit));
      setTimeout(() => {
        bindAuditPanelBtns(audit);
        // Panel schedule toggle
        $('.fp-panel-sched-toggle')?.addEventListener('change', async function() {
          const url = this.dataset.url;
          if (!url) return;
          if (this.checked) {
            const freq = 'weekly';
            try {
              const sched = await apiAction('POST', '/api/audits/schedule', { url, frequency: freq });
              if (sched && !STATE.auditSchedules.find(s => s.url === url)) STATE.auditSchedules.push(sched);
              showToast('success', 'Audit planifié activé — hebdomadaire');
            } catch(_) {
              STATE.auditSchedules.push({ id:'sched_'+Date.now(), url, frequency: freq, nextRun: Date.now()+7*86400000, createdAt: Date.now() });
              showToast('success', 'Audit planifié activé — hebdomadaire');
            }
            openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit));
          } else {
            const existing = STATE.auditSchedules.find(s => s.url === url);
            if (existing) {
              try { await apiAction('DELETE', `/api/audits/schedule/${existing.id}`); } catch(_) {}
              STATE.auditSchedules = STATE.auditSchedules.filter(s => s.url !== url);
            }
            showToast('info', 'Audit planifié désactivé');
            openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit));
          }
        });
        // Panel schedule frequency selector
        $('.fp-panel-sched-freq')?.addEventListener('change', async function() {
          const url = this.dataset.url;
          if (!url) return;
          const existing = STATE.auditSchedules.find(s => s.url === url);
          if (!existing) return;
          try {
            const updated = await apiAction('PATCH', `/api/audits/schedule/${existing.id}`, { frequency: this.value });
            Object.assign(existing, updated || { frequency: this.value });
            showToast('success', `Fréquence mise à jour : ${this.options[this.selectedIndex].text}`);
          } catch(_) {
            existing.frequency = this.value;
            showToast('success', `Fréquence mise à jour : ${this.options[this.selectedIndex].text}`);
          }
        });
      }, 50);
    }));
    $$('.audit-export').forEach(btn => btn.addEventListener('click', async e => {
      e.stopPropagation();
      const audit = STATE.audits.find(a => a.id === btn.dataset.id);
      if (!audit) { exportAuditsCsv(STATE.audits); return; }
      btn.disabled = true;
      btn.textContent = '…';
      try {
        const host = (audit.url || '').replace(/^https?:\/\//, '').split('/')[0];
        const name = `Audit ${host} — ${new Date().toLocaleDateString('fr-FR')}`;
        const res = await apiAction('POST', '/api/reports', { name, auditId: audit.id, format: 'PDF' });
        const r = res || { id: 'r' + Date.now(), name };
        STATE.reports.unshift(r);
        showToast('success', 'Export PDF en cours…');
        downloadReportPdf(r.id, name);
      } catch(e2) {
        exportAuditsCsv([audit]);
      }
      btn.disabled = false;
      btn.textContent = '↓';
    }));
    $$('.audit-more').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      const audit = STATE.audits.find(a => a.id === btn.dataset.id);
      if (!audit) return;
      showCtxMenu(e, [
        { key:'view', icon:'eye',      label:'Voir les détails', action:()=>openFloatPanel('Détail de l\'audit',renderAuditDetailPanel(audit)) },
        { key:'copy', icon:'copy',     label:'Copier l\'URL',    action:()=>{ navigator.clipboard?.writeText(audit.url); showToast('success','URL copiée'); } },
        { key:'pdf',  icon:'download', label:'Exporter PDF',     action:()=>{ openFloatPanel('Détail de l\'audit',renderAuditDetailPanel(audit)); bindAuditPanelBtns(audit); } },
        { key:'pin',  icon:'pin',      label: audit.pinned?'Détacher':'Épingler', action:()=>{ audit.pinned=!audit.pinned; STATE.pinned['audit_'+audit.id]=audit.pinned; localStorage.setItem('fp-pinned',JSON.stringify(STATE.pinned)); showToast('success',audit.pinned?'Épinglé !':'Épingle retiré'); render(); } },
        { divider:true, key:'div' },
        { key:'del',  icon:'trash',    label:'Supprimer',         action:async()=>{ try { await apiAction('DELETE',`/api/audits/${audit.id}`); } catch(e){} STATE.audits=STATE.audits.filter(a=>a.id!==audit.id); showToast('error','Audit supprimé'); render(); }, danger:true },
      ]);
    }));

    // Audit row click → detail (skip if clicking checkbox)
    $$('#audits-tbody tr').forEach(row => row.addEventListener('click', e => {
      if (e.target.classList.contains('fp-audit-row-cb')) return;
      const audit = STATE.audits.find(a => a.id === row.dataset.auditId);
      if (audit) { openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit)); bindAuditPanelBtns(audit); }
    }));

    // Audit row context menu
    $$('#audits-tbody tr').forEach(row => row.addEventListener('contextmenu', e => {
      const audit = STATE.audits.find(a => a.id === row.dataset.auditId);
      if (!audit) return;
      showCtxMenu(e, [
        { key:'view', icon:'eye',      label:'Voir les détails', action:()=>{ openFloatPanel('Détail de l\'audit',renderAuditDetailPanel(audit)); bindAuditPanelBtns(audit); } },
        { key:'copy', icon:'copy',     label:'Copier l\'URL',    action:()=>{ navigator.clipboard?.writeText(audit.url); showToast('success','URL copiée'); } },
        { key:'pdf',  icon:'download', label:'Exporter PDF',     action:()=>{ openFloatPanel('Détail de l\'audit',renderAuditDetailPanel(audit)); bindAuditPanelBtns(audit); } },
        { key:'pin',  icon:'pin',      label:audit.pinned?'Détacher':'Épingler', action:()=>{ audit.pinned=!audit.pinned; STATE.pinned['audit_'+audit.id]=audit.pinned; localStorage.setItem('fp-pinned',JSON.stringify(STATE.pinned)); render(); } },
        { divider:true, key:'div' },
        { key:'del',  icon:'trash',    label:'Supprimer',        action:async()=>{ try { await apiAction('DELETE',`/api/audits/${audit.id}`); } catch(e){} STATE.audits=STATE.audits.filter(a=>a.id!==audit.id); showToast('error','Audit supprimé'); render(); }, danger:true },
      ]);
    }));

    // ── History sub-page handlers ──
    const histSel = $('#hist-site-sel');
    if (histSel) {
      histSel.addEventListener('change', e => {
        STATE.historySiteUrl = e.target.value;
        loadHistoryForUrl(STATE.historySiteUrl);
      });
      // Auto-load history from API if not yet cached (including empty [])
      if (STATE.historySiteUrl && STATE.auditHistory[STATE.historySiteUrl] === undefined) {
        loadHistoryForUrl(STATE.historySiteUrl);
      }
    }

    $('#hist-export-csv')?.addEventListener('click', () => {
      const url = STATE.historySiteUrl || '';
      const history = STATE.auditHistory[url] || STATE.audits.filter(a => a.url === url).sort((a,b)=>new Date(a.date)-new Date(b.date));
      if (!history.length) { showToast('warning','Aucune donnée à exporter'); return; }
      const rows = [['Date','Score','Statut','Vitesse','Issues','Origine']];
      history.forEach(h => rows.push([h.date?.slice(0,10)||'', h.score, scoreLabel(h.score), h.speed||'', h.issues||'', h.origin||'manual']));
      const csv = rows.map(r => r.map(v => `"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');
      const blob = new Blob([csv], { type:'text/csv' });
      const a = Object.assign(document.createElement('a'), { href:URL.createObjectURL(blob), download:`historique-seo-${url.replace(/[^a-z0-9]/gi,'-')}-${new Date().toISOString().slice(0,10)}.csv` });
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      showToast('success','CSV exporté');
    });

    // Chart hit circles — tooltip + click
    $$('.fp-hist-hit').forEach(circle => {
      circle.addEventListener('mouseover', e => {
        const tip = $('#fp-hist-tooltip');
        if (!tip) return;
        const wrap = circle.closest('.fp-hist-chart-wrap');
        const wrapRect = wrap?.getBoundingClientRect();
        const circleRect = circle.getBoundingClientRect();
        const x = circleRect.left - (wrapRect?.left || 0) + circleRect.width / 2;
        const y = circleRect.top - (wrapRect?.top || 0) - 70;
        const originLabel = circle.dataset.origin === 'auto' ? 'Audit automatique' : 'Audit manuel';
        const scoreNum = parseInt(circle.dataset.score) || 0;
        tip.querySelector('#fp-hist-tip-date').textContent = circle.dataset.date || '';
        tip.querySelector('#fp-hist-tip-score').textContent = circle.dataset.score + '/100';
        tip.querySelector('#fp-hist-tip-score').style.color = scoreColor(scoreNum);
        tip.querySelector('#fp-hist-tip-origin').textContent = originLabel;
        tip.style.display = 'block';
        tip.style.left = Math.max(0, x - 60) + 'px';
        tip.style.top = Math.max(0, y) + 'px';
      });
      circle.addEventListener('mouseleave', () => { const tip = $('#fp-hist-tooltip'); if (tip) tip.style.display = 'none'; });
      circle.addEventListener('click', () => {
        const audit = STATE.audits.find(a => a.id === circle.dataset.auditId)
          || (STATE.auditHistory[STATE.historySiteUrl||''] || []).find(a => a.id === circle.dataset.auditId);
        if (audit) {
          openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit));
          bindAuditPanelBtns(audit);
        }
      });
    });

    // History table row clicks
    $$('.fp-hist-row').forEach(tr => {
      tr.addEventListener('click', () => {
        const id = tr.dataset.histAuditId;
        const audit = STATE.audits.find(a => a.id === id)
          || (STATE.auditHistory[STATE.historySiteUrl||''] || []).find(a => a.id === id);
        if (audit) {
          openFloatPanel('Détail de l\'audit', renderAuditDetailPanel(audit));
          bindAuditPanelBtns(audit);
        }
      });
    });
  }

  if (route === 'monitors') {
    $('#monitor-check-all')?.addEventListener('click', async () => {
      showToast('info', 'Vérification de tous les monitors…');
      const mons = STATE.monitors || [];
      if (typeof window.FP_MONITORS_API !== 'undefined') {
        for (const m of mons) { try { await window.FP_MONITORS_API.ping(m.id); } catch(e) {} }
      }
    });
    $('#monitor-new-btn')?.addEventListener('click', () => { openFloatPanel('Nouveau monitor', renderNewMonitorPanel()); setupNewMonitorPanel(); });

    // ── Monitor bulk checkboxes ──
    $$('.fp-monitor-cb').forEach(cb => {
      cb.addEventListener('change', e => {
        e.stopPropagation();
        const id = cb.dataset.id;
        if (e.target.checked) { STATE.selectedMonitors.add(id); }
        else { STATE.selectedMonitors.delete(id); }
        const card = cb.closest('.fp-monitor-card');
        if (card) card.classList.toggle('fp-card-sel', STATE.selectedMonitors.has(id));
        syncBulkBar();
      });
      cb.addEventListener('click', e => e.stopPropagation());
    });
    $$('.fp-monitor-cb-wrap').forEach(wrap => wrap.addEventListener('click', e => e.stopPropagation()));

    $$('.fp-monitor-card').forEach(card => {
      const monitor = STATE.monitors.find(m => m.id === card.dataset.monitorId);
      if (!monitor) return;
      card.addEventListener('click', e => {
        if (e.target.classList.contains('fp-monitor-cb') || e.target.closest('.fp-monitor-cb-wrap')) return;
        // Ping button
        if (e.target.closest('.monitor-ping')) {
          e.stopPropagation();
          const pingId = (e.target.closest('.monitor-ping').dataset.id) || monitor.id;
          if (typeof window.FP_MONITORS_API !== 'undefined') { window.FP_MONITORS_API.ping(pingId); }
          else { showToast('success', 'Ping envoyé pour ' + escHtml(monitor.name)); }
          return;
        }
        // Delete button
        if (e.target.closest('.monitor-del')) {
          e.stopPropagation();
          if (!confirm('Supprimer ' + monitor.name + ' ?')) return;
          apiAction('DELETE', '/api/monitors/' + monitor.id).catch(() => {}).finally(() => {
            STATE.monitors = STATE.monitors.filter(m => m.id !== monitor.id);
            showToast('error', 'Monitor supprimé'); render();
          });
          return;
        }
        openMonitorPanel(monitor);
      });
      card.addEventListener('contextmenu', e => {
        showCtxMenu(e, [
          { key:'test', icon:'refresh', label:'Tester maintenant', action:()=>{ if(typeof window.FP_MONITORS_API!=='undefined'){ window.FP_MONITORS_API.ping(monitor.id); } else { showToast('success', 'Test lancé pour ' + escHtml(monitor.name)); } } },
          { key:'copy', icon:'copy',    label:'Copier l\'URL',     action:()=>{ navigator.clipboard?.writeText(monitor.url); showToast('success','URL copiée'); } },
          { divider:true, key:'div' },
          { key:'del',  icon:'trash',   label:'Supprimer',          action:async()=>{ try { await apiAction('DELETE',`/api/monitors/${monitor.id}`); } catch(e){} STATE.monitors=STATE.monitors.filter(m=>m.id!==monitor.id); showToast('error','Monitor supprimé'); render(); }, danger:true },
        ]);
      });
    });
    $$('.monitor-cfg-save').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.dataset.monitorId;
        const emailInput = document.querySelector(`.monitor-cfg-email[data-monitor-id="${id}"]`);
        const phoneInput = document.querySelector(`.monitor-cfg-phone[data-monitor-id="${id}"]`);
        const criticalInput = document.querySelector(`.monitor-cfg-critical[data-monitor-id="${id}"]`);
        const emailVal = emailInput?.value.trim() || '';
        const phoneVal = phoneInput?.value.trim() || '';
        const isCritical = criticalInput?.checked ?? false;
        try {
          const updated = await apiAction('PATCH', `/api/monitors/${id}`, { alertEmail: emailVal, alertPhone: phoneVal, isCritical });
          const m = STATE.monitors.find(x => x.id === id);
          if (m) { m.alertEmail = updated?.alertEmail ?? emailVal; m.alertPhone = updated?.alertPhone ?? phoneVal; m.isCritical = updated?.isCritical ?? isCritical; }
          showToast('success', 'Alertes email + SMS mis à jour');
        } catch(e) { showToast('error', 'Erreur lors de la mise à jour'); }
      });
    });
    $$('.monitor-cfg-save-phone').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.dataset.monitorId;
        const phoneInput = document.querySelector(`.monitor-cfg-phone[data-monitor-id="${id}"]`);
        const phone = phoneInput?.value.trim() || '';
        if (phone && !/^\+\d{7,15}$/.test(phone.replace(/\s/g,''))) {
          showToast('warning', 'Format invalide — utilisez +336XXXXXXXX'); return;
        }
        try {
          const updated = await apiAction('PATCH', `/api/monitors/${id}`, { alertPhone: phone });
          const m = STATE.monitors.find(x => x.id === id);
          if (m) m.alertPhone = updated?.alertPhone ?? phone;
          showToast('success', phone ? 'SMS configuré ✓' : 'SMS désactivé');
        } catch(e) {
          const m = STATE.monitors.find(x => x.id === id);
          if (m) m.alertPhone = phone;
          showToast('success', phone ? 'SMS configuré ✓' : 'SMS désactivé');
        }
      });
    });
    $$('.monitor-cfg-test-sms').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.dataset.monitorId;
        const phoneInput = document.querySelector(`.monitor-cfg-phone[data-monitor-id="${id}"]`);
        const phone = phoneInput?.value.trim() || STATE.monitors.find(x => x.id === id)?.alertPhone || '';
        if (!phone) { showToast('warning', 'Entrez d\'abord un numéro SMS'); return; }
        showToast('info', `Envoi SMS de test à ${escHtml(phone)}…`);
        try {
          await apiAction('POST', `/api/monitors/${id}/test-sms`, { phone });
          showToast('success', `SMS de test envoyé à ${escHtml(phone)}`);
        } catch(e) {
          showToast('success', `SMS de test envoyé à ${escHtml(phone)}`);
        }
      });
    });
  }

  if (route === 'missions') {
    $$('[data-mission-filter]').forEach(btn => btn.addEventListener('click', () => { STATE.missionFilter = btn.dataset.missionFilter; render(); }));
    $('#mission-search')?.addEventListener('input', e => { STATE.missionSearch = e.target.value; render(); });
    $('#mission-sort')?.addEventListener('change', e => { STATE.missionSort = e.target.value; render(); });
    $$('#mission-view-toggle .fp-view-toggle-btn').forEach(btn => btn.addEventListener('click', () => {
      STATE.missionView = btn.dataset.view;
      if (['kanban','calendar','library'].includes(btn.dataset.view)) STATE.missionFilter = 'all';
      render();
    }));
    $('#mission-add-btn')?.addEventListener('click', async () => {
      const title = $('#mission-title-input')?.value.trim();
      if (!title) { showToast('warning','Entrez un titre'); return; }
      const newMs = { id:'ms'+Date.now(), title, category:$('#mission-cat-input')?.value||'Audits', impact:$('#mission-impact-input')?.value||'Élevé', status:'todo', date:new Date().toISOString().slice(0,10) };
      STATE.missions.push(newMs);
      saveMissions();
      logActivityEvent('team', `Mission créée : ${title}`, { missionId: newMs.id, category: newMs.category });
      showToast('success','Mission créée !');
      render();
      // Persistance backend
      if (typeof window.FP_MISSIONS_API !== 'undefined') {
        const saved = await window.FP_MISSIONS_API.create(newMs);
        if (saved && saved.id && saved.id !== newMs.id) {
          const idx = STATE.missions.findIndex(x => x.id === newMs.id);
          if (idx >= 0) STATE.missions[idx].id = saved.id;
          saveMissions();
        }
      }
    });
    $('#mission-title-input')?.addEventListener('keydown', e => { if(e.key==='Enter') $('#mission-add-btn')?.click(); });
    $$('.mission-check').forEach(cb => cb.addEventListener('change', () => {
      const m = STATE.missions.find(x => x.id === cb.dataset.id);
      if (m) {
        m.status = cb.checked ? 'done' : 'todo';
        saveMissions();
        render();
        if (typeof window.FP_MISSIONS_API !== 'undefined') window.FP_MISSIONS_API.update(m.id, { status: m.status }).catch(() => {});
      }
    }));
    $$('.mission-view').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      const m = STATE.missions.find(x => x.id === (btn.dataset.id || btn.dataset.missionId));
      if (!m) return;
      openFloatPanel('Mission — ' + m.title.slice(0, 32) + (m.title.length > 32 ? '…' : ''), renderMissionDetail(m));
      bindMissionDetailHandlers(m.id);
    }));
    $$('.mission-delete').forEach(btn => btn.addEventListener('click', e => {
      e.stopPropagation();
      const delId = btn.dataset.id;
      STATE.missions = STATE.missions.filter(m => m.id !== delId);
      saveMissions();
      showToast('error','Mission supprimée');
      render();
      if (typeof window.FP_MISSIONS_API !== 'undefined') window.FP_MISSIONS_API.delete(delId).catch(() => {});
    }));
    // Library add handler
    $$('.lib-add-mission').forEach(card => {
      card.addEventListener('click', e => {
        if (e.target.closest('.fp-lib-add-btn') || e.target.closest('.fp-lib-card')) {
          try {
            const title = card.dataset.libTitle;
            const stepsRaw = JSON.parse(card.dataset.libSteps || '[]');
            const steps = stepsRaw.map((t, i) => ({ id:'s'+Date.now()+i, text:t, done:false, tag:'Étape '+(i+1) }));
            const libMs = { id:'ms'+Date.now(), title, category:card.dataset.libCat||'SEO Technique', impact:card.dataset.libImpact||'Élevé', status:'todo', date:new Date(Date.now()+7*86400000).toISOString().slice(0,10), steps };
            STATE.missions.push(libMs);
            saveMissions();
            showToast('success', 'Mission ajoutée : ' + title.slice(0,40));
            card.style.opacity = '0.4';
            card.style.pointerEvents = 'none';
            if (typeof window.FP_MISSIONS_API !== 'undefined') window.FP_MISSIONS_API.create(libMs).catch(() => {});
          } catch(err) { showToast('error','Erreur lors de l\'ajout'); }
        }
      });
    });

    $$('.fp-mission-row').forEach(row => {
      const m = STATE.missions.find(x => x.id === row.dataset.missionId);
      if (!m) return;
      row.addEventListener('click', () => {
        openFloatPanel('Mission — ' + m.title.slice(0, 32) + (m.title.length > 32 ? '…' : ''), renderMissionDetail(m));
        bindMissionDetailHandlers(m.id);
      });
      row.addEventListener('contextmenu', e => {
        e.preventDefault();
        showCtxMenu(e, [
          { key:'view',  icon:'eye',    label:'Voir les étapes', action:()=>{ openFloatPanel('Mission — ' + m.title.slice(0,32), renderMissionDetail(m)); bindMissionDetailHandlers(m.id); } },
          { key:'done',  icon:'check',  label: m.status==='done'?'Remettre à faire':'Marquer terminé', action:()=>{ const wasDone=m.status==='done'; m.status=wasDone?'todo':'done'; saveMissions(); if(!wasDone) logActivityEvent('team',`Mission terminée : ${m.title}`,{missionId:m.id}); render(); if(typeof window.FP_MISSIONS_API!=='undefined') window.FP_MISSIONS_API.update(m.id,{status:m.status}).catch(()=>{}); } },
          { divider:true, key:'div' },
          { key:'del',   icon:'trash',  label:'Supprimer', action:()=>{ const dId=m.id; STATE.missions=STATE.missions.filter(x=>x.id!==dId); saveMissions(); showToast('error','Mission supprimée'); render(); if(typeof window.FP_MISSIONS_API!=='undefined') window.FP_MISSIONS_API.delete(dId).catch(()=>{}); }, danger:true },
        ]);
      });
    });
    // Kanban drag/drop
    if (STATE.missionView === 'kanban') {
      let dragId = null;
      $$('.fp-kanban-card').forEach(card => {
        card.addEventListener('dragstart', e => {
          dragId = card.dataset.missionId;
          card.classList.add('dragging');
          e.dataTransfer.effectAllowed = 'move';
        });
        card.addEventListener('dragend', () => {
          dragId = null;
          $$('.fp-kanban-card').forEach(c => c.classList.remove('dragging'));
          $$('.fp-kanban-col').forEach(c => c.classList.remove('drag-over'));
        });
      });
      $$('.fp-kanban-col').forEach(col => {
        col.addEventListener('dragover', e => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; col.classList.add('drag-over'); });
        col.addEventListener('dragleave', e => { if (!col.contains(e.relatedTarget)) col.classList.remove('drag-over'); });
        col.addEventListener('drop', e => {
          e.preventDefault();
          col.classList.remove('drag-over');
          const status = col.dataset.status;
          if (!dragId || !status) return;
          const mission = STATE.missions.find(m => m.id === dragId);
          if (mission && mission.status !== status) {
            mission.status = status;
            saveMissions();
            showToast('success', `"${escHtml(mission.title)}" → ${statusLabels[status]}`);
            render();
            if (typeof window.FP_MISSIONS_API !== 'undefined') window.FP_MISSIONS_API.update(mission.id, { status }).catch(() => {});
          }
        });
      });
    }

    // Calendar nav handlers
    $('#cal-prev')?.addEventListener('click', () => {
      STATE.calendarMonth--;
      if (STATE.calendarMonth < 0) { STATE.calendarMonth = 11; STATE.calendarYear--; }
      STATE.calendarSearch = '';
      STATE.calendarTypeFilter = '';
      STATE.calendarSelectedDate = null;
      render();
    });
    $('#cal-next')?.addEventListener('click', () => {
      STATE.calendarMonth++;
      if (STATE.calendarMonth > 11) { STATE.calendarMonth = 0; STATE.calendarYear++; }
      STATE.calendarSearch = '';
      STATE.calendarTypeFilter = '';
      STATE.calendarSelectedDate = null;
      render();
    });
    $('#cal-today')?.addEventListener('click', () => {
      STATE.calendarMonth = new Date().getMonth();
      STATE.calendarYear = new Date().getFullYear();
      STATE.calendarSearch = '';
      STATE.calendarTypeFilter = '';
      STATE.calendarSelectedDate = null;
      render();
    });

    // Calendar search / filter handlers
    $('#cal-search-input')?.addEventListener('input', e => {
      STATE.calendarSearch = e.target.value;
      const selStart = e.target.selectionStart;
      const selEnd = e.target.selectionEnd;
      render();
      const inp = $('#cal-search-input');
      if (inp) { inp.focus(); inp.setSelectionRange(selStart, selEnd); }
    });
    $('#cal-type-filter')?.addEventListener('change', e => {
      STATE.calendarTypeFilter = e.target.value;
      render();
    });
    $('#cal-search-clear')?.addEventListener('click', () => {
      STATE.calendarSearch = '';
      STATE.calendarTypeFilter = '';
      render();
    });

    // Calendar interactive — create / delete / drag-drop RDV
    if (STATE.missionView === 'calendar') {
      // Click on + button → create event
      $$('.fp-cal-add-btn').forEach(addBtn => {
        addBtn.addEventListener('click', e => {
          e.stopPropagation();
          const dateStr = addBtn.dataset.date;
          if (!dateStr) return;
          openFloatPanel('Nouveau RDV — ' + dateStr, renderNewCalEventPanel(dateStr));
          setupNewCalEventPanel(dateStr);
        });
      });

      // Click on day cell background → show daily agenda panel
      $$('.fp-cal-droptarget').forEach(cell => {
        cell.addEventListener('click', e => {
          if (e.target.closest('.fp-cal-add-btn') || e.target.closest('.fp-cal-event-del')) return;
          const dateStr = cell.dataset.date;
          if (!dateStr) return;
          STATE.calendarSelectedDate = (STATE.calendarSelectedDate === dateStr) ? null : dateStr;
          render();
        });
      });

      // Agenda panel close button
      $('#cal-agenda-close')?.addEventListener('click', () => {
        STATE.calendarSelectedDate = null;
        render();
      });

      // Agenda panel "+ RDV" button(s)
      $$('.fp-cal-agenda-add-rdv').forEach(btn => {
        btn.addEventListener('click', e => {
          e.stopPropagation();
          const dateStr = btn.dataset.date || STATE.calendarSelectedDate;
          if (!dateStr) return;
          openFloatPanel('Nouveau RDV — ' + dateStr, renderNewCalEventPanel(dateStr));
          setupNewCalEventPanel(dateStr);
        });
      });

      // Click on agenda RDV item → edit
      $$('.fp-agenda-item').forEach(item => {
        item.addEventListener('click', e => {
          if (e.target.closest('.fp-cal-event-del')) return;
          const id = item.dataset.calEventId;
          const ev = (STATE.calendarEvents || []).find(ce => ce.id === id);
          if (!ev) return;
          openFloatPanel('Modifier le RDV', renderEditCalEventPanel(ev));
          setupEditCalEventPanel(ev);
        });
      });

      // Click on agenda mission item → mission detail
      $$('.fp-agenda-mission-item').forEach(item => {
        item.addEventListener('click', () => {
          const m = STATE.missions.find(x => x.id === item.dataset.missionId);
          if (!m) return;
          openFloatPanel('Mission — ' + m.title.slice(0, 32) + (m.title.length > 32 ? '…' : ''), renderMissionDetail(m));
          bindMissionDetailHandlers(m.id);
        });
      });

      // Click on RDV pill → edit event (not on × delete button)
      $$('.fp-cal-rdv').forEach(rdv => {
        rdv.addEventListener('click', e => {
          if (e.target.closest('.fp-cal-event-del')) return;
          e.stopPropagation();
          const id = rdv.dataset.calEventId;
          const ev = (STATE.calendarEvents||[]).find(ce => ce.id === id);
          if (!ev) return;
          openFloatPanel('Modifier le RDV', renderEditCalEventPanel(ev));
          setupEditCalEventPanel(ev);
        });
      });

      // Delete calendar event (× button)
      $$('.fp-cal-event-del').forEach(delBtn => {
        delBtn.addEventListener('click', e => {
          e.stopPropagation();
          const id = delBtn.dataset.calEventId;
          STATE.calendarEvents = (STATE.calendarEvents||[]).filter(ce => ce.id !== id);
          saveCalendarEvents();
          showToast('error','RDV supprimé');
          render();
        });
      });

      // Drag & drop calendar events between dates
      let dragCalId = null;
      $$('.fp-cal-rdv[draggable]').forEach(el => {
        el.addEventListener('dragstart', e => {
          dragCalId = el.dataset.calEventId;
          el.classList.add('fp-cal-dragging');
          e.dataTransfer.effectAllowed = 'move';
        });
        el.addEventListener('dragend', () => {
          dragCalId = null;
          $$('.fp-cal-rdv').forEach(x => x.classList.remove('fp-cal-dragging'));
          $$('.fp-cal-droptarget').forEach(c => c.classList.remove('fp-cal-drag-over'));
        });
      });
      $$('.fp-cal-droptarget').forEach(cell => {
        cell.addEventListener('dragover', e => {
          if (!dragCalId) return;
          e.preventDefault();
          e.dataTransfer.dropEffect = 'move';
          cell.classList.add('fp-cal-drag-over');
        });
        cell.addEventListener('dragleave', e => {
          if (!cell.contains(e.relatedTarget)) cell.classList.remove('fp-cal-drag-over');
        });
        cell.addEventListener('drop', e => {
          e.preventDefault();
          cell.classList.remove('fp-cal-drag-over');
          const newDate = cell.dataset.date;
          if (!dragCalId || !newDate) return;
          const ev = (STATE.calendarEvents||[]).find(ce => ce.id === dragCalId);
          if (ev && ev.date !== newDate) {
            ev.date = newDate;
            saveCalendarEvents();
            showToast('success',`"${escHtml(ev.title)}" déplacé au ${newDate}`);
            render();
          }
          dragCalId = null;
        });
      });
    }

    $$('.fp-mission-row').forEach(row => {
      row.addEventListener('mouseenter', () => row.style.background = 'rgba(37,99,235,0.04)');
      row.addEventListener('mouseleave', () => row.style.background = '');
      row.addEventListener('contextmenu', e => {
        const m = STATE.missions.find(x => x.id === row.dataset.missionId);
        if (!m) return;
        showCtxMenu(e, [
          { key:'done', icon:'check', label:m.status==='done'?'Marquer À faire':'Marquer Terminé', action:()=>{ const wasDone=m.status==='done'; m.status=wasDone?'todo':'done'; saveMissions(); if(!wasDone) logActivityEvent('team',`Mission terminée : ${m.title}`,{missionId:m.id}); render(); if(typeof window.FP_MISSIONS_API!=='undefined') window.FP_MISSIONS_API.update(m.id,{status:m.status}).catch(()=>{}); } },
          { key:'dup',  icon:'copy',  label:'Dupliquer', action:()=>{ const dup={...m,id:'ms'+Date.now(),title:'[Copie] '+m.title}; STATE.missions.push(dup); saveMissions(); render(); showToast('success','Mission dupliquée'); if(typeof window.FP_MISSIONS_API!=='undefined') window.FP_MISSIONS_API.create(dup).catch(()=>{}); } },
          { divider:true, key:'div' },
          { key:'del',  icon:'trash', label:'Supprimer', action:()=>{ const dId=m.id; STATE.missions=STATE.missions.filter(x=>x.id!==dId); saveMissions(); showToast('error','Mission supprimée'); render(); if(typeof window.FP_MISSIONS_API!=='undefined') window.FP_MISSIONS_API.delete(dId).catch(()=>{}); }, danger:true },
        ]);
      });
    });
  }

  if (route === 'reports') {
    $$('[data-report-dl]').forEach(btn => btn.addEventListener('click', async e => {
      e.stopPropagation();
      const reportId = btn.dataset.reportDl;
      const report = STATE.reports.find(r => r.id === reportId);
      if (report?.id) {
        downloadReportPdf(report.id, report.name || 'rapport');
        showToast('success', 'Téléchargement PDF…');
      } else {
        exportReportsCsv();
      }
    }));
    $$('[data-report-share]').forEach(btn => btn.addEventListener('click', async e => {
      e.stopPropagation();
      const reportId = btn.dataset.reportShare;
      const report = STATE.reports.find(r => r.id === reportId);
      const branding = JSON.parse(localStorage.getItem('fp-wl-branding') || '{}');
      const brandingPayload = {
        agencyName:     branding.agencyName    || STATE.me?.org?.name || 'Mon Agence',
        logoUrl:        branding.logoUrl       || '',
        primaryColor:   branding.primaryColor  || '#2563EB',
        secondaryColor: branding.secondaryColor|| '#1d4ed8',
        footerMsg:      branding.footerMsg     || '',
      };
      try {
        const res = await apiAction('POST', `/api/reports/${reportId}/share`, {
          branding: brandingPayload,
          auditIds: STATE.audits.slice(0, 4).map(a => a.id),
        });
        if (res?.token) {
          if (report) { report.shared = true; }
          const base = location.pathname.endsWith('dashboard.html')
            ? location.pathname.replace('dashboard.html', 'report-view.html')
            : location.pathname.replace(/\/?$/, '/report-view.html');
          const shareUrl = `${location.origin}${base}?token=${res.token}`;
          navigator.clipboard?.writeText(shareUrl).catch(() => {});
          showToast('success', 'Lien copié ! Valable 30 jours.');
          return;
        }
      } catch(err) {
        console.warn('[FP] Share API failed, using local fallback', err);
      }
      const token = 'fp-' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
      let _shareNotes = [];
      try { if (report?.meetingNotesJson) _shareNotes = JSON.parse(report.meetingNotesJson); } catch {}
      const payload = {
        report: report || { id: reportId, name: 'Rapport', date: new Date().toISOString(), type: 'PDF', pages: 8 },
        branding: brandingPayload,
        audits: STATE.audits.slice(0, 4),
        meetingNotes: _shareNotes,
        createdAt: new Date().toISOString(),
        expiresAt: new Date(Date.now() + 30 * 24 * 3600 * 1000).toISOString(),
      };
      localStorage.setItem('fp-share-' + token, JSON.stringify(payload));
      if (report) { report.shared = true; }
      const base = location.pathname.endsWith('dashboard.html')
        ? location.pathname.replace('dashboard.html', 'report-view.html')
        : location.pathname.replace(/\/?$/, '/report-view.html');
      const shareUrl = `${location.origin}${base}?token=${token}`;
      navigator.clipboard?.writeText(shareUrl).catch(() => {});
      showToast('success', 'Lien copié ! Valable 30 jours.');
    }));
    $('#report-new-btn')?.addEventListener('click', () => { openFloatPanel('Générer un rapport PDF', renderNewReportPanel()); setupNewReportPanel(); });
    $$('.fp-report-card, .fp-report-row').forEach(card => {
      const report = STATE.reports.find(r => r.id === card.dataset.reportId);
      if (!report) return;
      card.addEventListener('contextmenu', e => {
        showCtxMenu(e, [
          { key:'dl',    icon:'download', label:'Télécharger', action:()=>{ downloadReportPdf(report.id, report.name||'rapport'); showToast('success','Téléchargement PDF…'); } },
          { key:'share', icon:'copy',     label:'Copier le lien', action: async ()=>{
            const wlb = JSON.parse(localStorage.getItem('fp-wl-branding') || '{}');
            const bp = { agencyName: wlb.agencyName || STATE.me?.org?.name || 'Mon Agence', logoUrl: wlb.logoUrl || '', primaryColor: wlb.primaryColor || '#2563EB', secondaryColor: wlb.secondaryColor || '#1d4ed8', footerMsg: wlb.footerMsg || '' };
            const base = location.pathname.endsWith('dashboard.html') ? location.pathname.replace('dashboard.html','report-view.html') : location.pathname.replace(/\/?$/,'/report-view.html');
            try {
              const res = await apiAction('POST', `/api/reports/${report.id}/share`, { branding: bp, auditIds: STATE.audits.slice(0,4).map(a=>a.id) });
              if (res?.token) { navigator.clipboard?.writeText(`${location.origin}${base}?token=${res.token}`).catch(()=>{}); showToast('success','Lien copié ! Valable 30 jours.'); return; }
            } catch(err) { console.warn('[FP] Share API fallback'); }
            const token = 'fp-'+Math.random().toString(36).slice(2,10)+Date.now().toString(36);
            let _ctxNotes = []; try { if (report?.meetingNotesJson) _ctxNotes = JSON.parse(report.meetingNotesJson); } catch {}
            localStorage.setItem('fp-share-'+token, JSON.stringify({ report, branding:bp, audits:STATE.audits.slice(0,4), meetingNotes:_ctxNotes, createdAt:new Date().toISOString(), expiresAt:new Date(Date.now()+30*24*3600*1000).toISOString() }));
            navigator.clipboard?.writeText(`${location.origin}${base}?token=${token}`).catch(()=>{});
            showToast('success','Lien copié ! Valable 30 jours.');
          } },
          { key:'regen', icon:'refresh',  label:'Regénérer', action:async()=>{
            try {
              const res = await apiAction('POST', '/api/reports', { name: report.name, format: report.type || 'PDF' });
              if (res) { const idx = STATE.reports.findIndex(x=>x.id===report.id); if(idx>=0) STATE.reports.splice(idx,1); STATE.reports.unshift(res); }
              showToast('success','Rapport régénéré !'); render();
            } catch(e) { showToast('error','Erreur lors de la régénération'); }
          } },
          { divider:true, key:'div' },
          { key:'del',   icon:'trash',    label:'Supprimer',   action:async()=>{ try { await apiAction('DELETE',`/api/reports/${report.id}`); } catch(e){} STATE.reports=STATE.reports.filter(r=>r.id!==report.id); showToast('error','Rapport supprimé'); render(); }, danger:true },
        ]);
      });
    });
  }

  if (route === 'billing') {
    $$('.fp-free-module-btn').forEach(btn => btn.addEventListener('click', () => {
      const key = btn.dataset.moduleKey;
      if (!key || !(key in STATE.freeModules)) return;
      STATE.freeModules[key] = !STATE.freeModules[key];
      localStorage.setItem('fp-free-modules', JSON.stringify(STATE.freeModules));
      applyFreeModules();
      navigate(STATE.route);
      showToast('success', STATE.freeModules[key] ? 'Module activé !' : 'Module désactivé');
    }));
    $$('.fp-addon-btn').forEach(btn => btn.addEventListener('click', () => {
      showToast('info', 'Redirection vers la gestion des modules…');
      setTimeout(() => { window.location.href = '/addons.html'; }, 1000);
    }));
    $('#billing-change-plan')?.addEventListener('click', () => {
      const plans = [
        {name:'Starter', price:'29€', features:['50 audits/mois','5 monitors','1 utilisateur']},
        {name:'Pro',     price:'79€', features:['300 audits/mois','50 monitors','5 utilisateurs','White Label']},
        {name:'Agency',  price:'199€',features:['Illimité','200 monitors','15 utilisateurs','API accès','SLA 99.9%']},
      ];
      openFloatPanel('Changer de plan', `
        <div style="display:flex;flex-direction:column;gap:12px">
          ${plans.map(p=>`
            <div class="fp-card fp-card-sm" style="${p.name==='Pro'?'border-color:#2563EB':''}">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
                <span style="font-size:14px;font-weight:700;color:var(--fp-text)">${p.name}</span>
                <span style="font-size:16px;font-weight:800;color:#2563EB;font-family:var(--fp-font-head)">${p.price}/mois</span>
              </div>
              ${p.features.map(f=>`<div style="font-size:11px;color:var(--fp-text-muted);margin-bottom:4px">✓ ${f}</div>`).join('')}
              <button class="fp-btn fp-btn-sm ${p.name===STATE.me?.plan?'fp-btn-ghost':'fp-btn-primary'}" data-checkout-plan="${p.name.toLowerCase()}" style="margin-top:10px;width:100%;${p.name===STATE.me?.plan?'opacity:0.5;cursor:default':''}">
                ${p.name===STATE.me?.plan?'Plan actuel':'Choisir'}
              </button>
            </div>
          `).join('')}
        </div>
      `);
      // Bind checkout buttons after panel renders
      setTimeout(() => {
        $$('[data-checkout-plan]').forEach(checkBtn => {
          if (checkBtn.dataset.checkoutPlan === (STATE.me?.plan||'').toLowerCase()) return;
          checkBtn.addEventListener('click', async () => {
            const plan = checkBtn.dataset.checkoutPlan;
            checkBtn.disabled = true;
            checkBtn.textContent = 'Redirection…';
            showToast('info', 'Ouverture du paiement Stripe…');
            try {
              const res = await apiAction('POST', '/api/billing/checkout', { plan });
              if (res?.url) {
                window.location.href = res.url;
              } else {
                showToast('error', 'Impossible de démarrer le paiement');
                checkBtn.disabled = false;
                checkBtn.textContent = 'Choisir';
              }
            } catch(e) {
              showToast('error', 'Erreur Stripe — réessayez');
              checkBtn.disabled = false;
              checkBtn.textContent = 'Choisir';
            }
          });
        });
      }, 80);
    });
    $('#billing-manage')?.addEventListener('click', async () => {
      showToast('info','Ouverture du portail Stripe…');
      try {
        const res = await apiAction('POST', '/api/billing/portal');
        if (res?.url) {
          window.open(res.url, '_blank', 'noopener,noreferrer');
        } else {
          showToast('error','Impossible d\'ouvrir le portail de facturation');
        }
      } catch(e) {
        showToast('error','Erreur lors de l\'ouverture du portail Stripe');
      }
    });
  }

  if (route === 'local-seo') {
    $$('.fp-check-item').forEach(item => item.addEventListener('click', () => {
      const c = STATE.checklist.find(x => x.id === item.dataset.checkId);
      if (c) { c.done = !c.done; saveChecklist(); render(); }
    }));
    // Init Google Map after DOM is ready
    setTimeout(initLocalSEOMap, 50);
  }

  if (route === 'team') {
    $$('.fp-team-member-row').forEach(row => {
      const memberId = row.dataset.memberId;
      const member = STATE.team.find(t => t.id === memberId);
      if (!member || member.role === 'owner') return;
      row.addEventListener('contextmenu', e => {
        showCtxMenu(e, [
          { key:'role',  icon:'filter', label:'Changer le rôle', action:()=>changeTeamMemberRole(member.id, member.role) },
          { key:'msg',   icon:'send',   label:'Envoyer message', action:()=>showToast('success',`Message envoyé à ${escHtml(member.name)} !`) },
          { divider:true, key:'div' },
          { key:'del',   icon:'trash',  label:'Retirer du projet', action:async()=>{ try { await apiAction('DELETE',`/api/team/${member.id}`); } catch(e){} STATE.team=STATE.team.filter(t=>t.id!==member.id); showToast('error',escHtml(member.name)+' retiré'); render(); }, danger:true },
        ]);
      });
    });
    $('#team-invite-btn')?.addEventListener('click', () => {
      openFloatPanel('Inviter un membre', renderInvitePanel());
      setTimeout(() => {
        $('#invite-send')?.addEventListener('click', async () => {
          const email = $('#invite-email')?.value.trim();
          const role = $('#invite-role')?.value || 'Editor';
          if (!email) { showToast('warning','Entrez un email'); return; }
          try {
            await apiAction('POST', '/api/team/invite', { email, role });
            showToast('success',`Invitation envoyée à ${escHtml(email)} !`);
          } catch(e) { showToast('error','Erreur lors de l\'invitation'); return; }
          closeFloatPanel();
        });
      }, 50);
    });
    $$('[data-remove-member]').forEach(btn => btn.addEventListener('click', () => showToast('error','Membre retiré')));
    const sendChat = async () => {
      const input = $('#team-chat-input');
      if (!input?.value.trim()) return;
      const now = new Date();
      const time = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
      const msg = input.value;
      const from = STATE.me?.firstName || 'Vous';
      STATE.teamChatHistory.push({ from, msg, time });
      localStorage.setItem('fp-chat', JSON.stringify(STATE.teamChatHistory));
      input.value = '';
      render();
      setTimeout(() => { const msgs = $('#team-chat-msgs'); if(msgs) msgs.scrollTop = msgs.scrollHeight; }, 50);
      // Persistance backend (best-effort)
      if (typeof window.FP_CHAT_API !== 'undefined') {
        window.FP_CHAT_API.send('team', msg).catch(() => {});
      }
    };
    $('#team-chat-send')?.addEventListener('click', sendChat);
    $('#team-chat-input')?.addEventListener('keydown', e => { if(e.key==='Enter') sendChat(); });
  }

  if (route === 'settings') {
    $$('[data-toggle]').forEach(toggle => toggle.addEventListener('click', () => {
      const key = toggle.dataset.toggle;
      STATE.settings[key] = !STATE.settings[key];
      toggle.classList.toggle('on', STATE.settings[key]);
      toggle.setAttribute('aria-pressed', STATE.settings[key]);
      if (key === 'themeAuto') { STATE.theme = STATE.settings.themeAuto ? 'dark' : STATE.theme; applyTheme(); }
    }));
    $('#settings-save')?.addEventListener('click', () => { saveSettings(); showToast('success','Paramètres sauvegardés !'); });
    $('#logout-all')?.addEventListener('click', () => {
      ['fp-token','fp-auth','fp-session','fp-user'].forEach(k => localStorage.removeItem(k));
      sessionStorage.clear();
      showToast('success', 'Toutes les sessions fermées');
      setTimeout(() => { window.location.href = '/login.html'; }, 1200);
    });
    $('#renew-access')?.addEventListener('click', () => showToast('success','Lien envoyé par email'));

    if (STATE.subRoute === 'alerts') {
      $('#show-add-rule-form')?.addEventListener('click', () => {
        const form = $('#add-rule-form');
        if (form) form.style.display = form.style.display === 'none' ? 'block' : 'none';
      });
      $('#cancel-rule-form')?.addEventListener('click', () => {
        const form = $('#add-rule-form');
        if (form) form.style.display = 'none';
      });
      $('#save-alert-rule')?.addEventListener('click', async () => {
        const name = $('#rule-name')?.value.trim();
        const type = $('#rule-type')?.value;
        const operator = $('#rule-operator')?.value;
        const threshold = parseFloat($('#rule-threshold')?.value);
        const durationMin = parseInt($('#rule-duration')?.value || '0', 10);
        const channels = [];
        if ($('#rule-ch-email')?.checked) channels.push('email');
        if ($('#rule-ch-sms')?.checked) channels.push('sms');
        const siteUrls = [...$$('.new-rule-site:checked')].map(cb => cb.dataset.url).filter(Boolean);
        if (!name || !type || !operator || isNaN(threshold)) {
          showToast('error', 'Remplissez tous les champs obligatoires'); return;
        }
        try {
          const rule = await apiAction('POST', '/api/alert-rules', { name, type, operator, threshold, durationMin, channels, siteUrls, enabled: true });
          if (rule) {
            STATE.alertRules.push(rule);
            showToast('success', `Règle "${name}" créée !`);
            navigateSub('alerts');
          }
        } catch(e) { showToast('error', 'Erreur lors de la création de la règle'); }
      });

      $$('[data-toggle-rule]').forEach(btn => {
        btn.addEventListener('click', async () => {
          const ruleId = btn.dataset.toggleRule;
          const rule = STATE.alertRules.find(r => r.id === ruleId);
          if (!rule) return;
          const newEnabled = !rule.enabled;
          try {
            await apiAction('PATCH', `/api/alert-rules/${ruleId}`, { enabled: newEnabled });
            rule.enabled = newEnabled;
            btn.classList.toggle('on', newEnabled);
            btn.setAttribute('aria-pressed', newEnabled);
            const row = btn.closest('[data-rule-id]');
            const badge = row?.querySelector('span');
            if (badge) {
              badge.textContent = newEnabled ? 'Active' : 'Inactive';
              badge.style.cssText = newEnabled
                ? 'font-size:10px;padding:2px 8px;border-radius:999px;font-weight:600;background:rgba(34,197,94,0.15);color:#22c55e;border:1px solid rgba(34,197,94,0.3)'
                : 'font-size:10px;padding:2px 8px;border-radius:999px;font-weight:600;background:rgba(255,255,255,0.05);color:var(--fp-text-faint);border:1px solid var(--fp-border)';
            }
            showToast('success', `Règle ${newEnabled ? 'activée' : 'désactivée'}`);
          } catch(e) { showToast('error', 'Erreur lors de la mise à jour'); }
        });
      });

      $$('[data-delete-rule]').forEach(btn => {
        btn.addEventListener('click', async () => {
          const ruleId = btn.dataset.deleteRule;
          const rule = STATE.alertRules.find(r => r.id === ruleId);
          if (!rule) return;
          try {
            await apiAction('DELETE', `/api/alert-rules/${ruleId}`, null);
            STATE.alertRules = STATE.alertRules.filter(r => r.id !== ruleId);
            showToast('success', `Règle "${rule.name}" supprimée`);
            navigateSub('alerts');
          } catch(e) { showToast('error', 'Erreur lors de la suppression'); }
        });
      });

      $$('[data-edit-rule]').forEach(btn => {
        btn.addEventListener('click', () => {
          const ruleId = btn.dataset.editRule;
          const formEl = $(`#edit-rule-form-${ruleId}`);
          if (!formEl) return;
          const isOpen = formEl.style.display !== 'none';
          $$('[id^="edit-rule-form-"]').forEach(f => { f.style.display = 'none'; });
          formEl.style.display = isOpen ? 'none' : 'block';
        });
      });

      $$('.cancel-edit-rule').forEach(btn => {
        btn.addEventListener('click', () => {
          const ruleId = btn.dataset.rule;
          const formEl = $(`#edit-rule-form-${ruleId}`);
          if (formEl) formEl.style.display = 'none';
        });
      });

      $$('.save-edit-rule').forEach(btn => {
        btn.addEventListener('click', async () => {
          const ruleId = btn.dataset.rule;
          const rule = STATE.alertRules.find(r => r.id === ruleId);
          if (!rule) return;
          const formEl = $(`#edit-rule-form-${ruleId}`);
          if (!formEl) return;
          const name = formEl.querySelector('.edit-rule-name')?.value.trim();
          const type = formEl.querySelector('.edit-rule-type')?.value;
          const operator = formEl.querySelector('.edit-rule-operator')?.value;
          const threshold = parseFloat(formEl.querySelector('.edit-rule-threshold')?.value);
          const durationMin = parseInt(formEl.querySelector('.edit-rule-duration')?.value || '0', 10);
          const channels = [];
          if (formEl.querySelector('.edit-rule-ch-email')?.checked) channels.push('email');
          if (formEl.querySelector('.edit-rule-ch-sms')?.checked) channels.push('sms');
          const siteUrls = [...formEl.querySelectorAll('.edit-rule-site:checked')].map(cb => cb.dataset.url).filter(Boolean);
          if (!name || !type || !operator || isNaN(threshold)) {
            showToast('error', 'Remplissez tous les champs obligatoires'); return;
          }
          try {
            const updated = await apiAction('PATCH', `/api/alert-rules/${ruleId}`, { name, type, operator, threshold, durationMin, channels, siteUrls });
            if (updated) {
              Object.assign(rule, updated);
              showToast('success', `Règle "${name}" mise à jour`);
              navigateSub('alerts');
            }
          } catch(e) { showToast('error', 'Erreur lors de la mise à jour'); }
        });
      });

      const TEMPLATES = [
        { name: 'Score SEO critique', type: 'seo_score', operator: 'lt', threshold: 50, durationMin: 0, channels: ['email'], siteUrls: [] },
        { name: 'Latence élevée (> 1s)', type: 'latency', operator: 'gt', threshold: 1000, durationMin: 5, channels: ['email'], siteUrls: [] },
        { name: 'Uptime faible (< 98%)', type: 'uptime', operator: 'lt', threshold: 98, durationMin: 10, channels: ['email', 'sms'], siteUrls: [] },
      ];
      $('#dismiss-templates')?.addEventListener('click', () => {
        localStorage.setItem('fp-alert-templates-first-access', 'done');
        navigateSub('alerts');
      });

      $$('[data-apply-template]').forEach(btn => {
        btn.addEventListener('click', async () => {
          const idx = parseInt(btn.dataset.applyTemplate, 10);
          const t = TEMPLATES[idx];
          if (!t) return;
          try {
            const rule = await apiAction('POST', '/api/alert-rules', t);
            if (rule) {
              STATE.alertRules.push(rule);
              // Mark first-access as done once user activates a template
              localStorage.setItem('fp-alert-templates-first-access', 'done');
              showToast('success', `Template "${t.name}" activé !`);
              navigateSub('alerts');
            }
          } catch(e) { showToast('error', 'Erreur lors de l\'activation du template'); }
        });
      });
    }

    const syncColorHex = (pickerId, hexId) => {
      const picker = $(pickerId);
      const hexInput = $(hexId);
      if (!picker || !hexInput) return;
      picker.addEventListener('input', () => { hexInput.value = picker.value; });
      hexInput.addEventListener('input', () => {
        const v = hexInput.value.trim();
        if (/^#[0-9a-fA-F]{6}$/.test(v)) picker.value = v;
      });
    };
    syncColorHex('#wl-primary-color', '#wl-primary-color-hex');
    syncColorHex('#wl-secondary-color', '#wl-secondary-color-hex');

    $('#wl-save-branding')?.addEventListener('click', () => {
      const branding = {
        logoUrl:        $('#wl-logo-url')?.value.trim() || '',
        agencyName:     $('#wl-agency-name')?.value.trim() || '',
        primaryColor:   $('#wl-primary-color-hex')?.value.trim() || '#2563EB',
        secondaryColor: $('#wl-secondary-color-hex')?.value.trim() || '#1d4ed8',
        footerMsg:      $('#wl-footer-msg')?.value.trim() || '',
      };
      localStorage.setItem('fp-wl-branding', JSON.stringify(branding));
      showToast('success', 'Branding White Label sauvegardé !');
      render();
    });
  }

  if (route === 'ai') {
    $$('.fp-ai-quick').forEach(btn => btn.addEventListener('click', () => sendAIMessage(btn.dataset.aiPrompt)));
    const aiInput = $('#ai-input');
    const aiSend = $('#ai-send');
    aiSend?.addEventListener('click', () => { sendAIMessage(aiInput?.value||''); if(aiInput) aiInput.value=''; });
    aiInput?.addEventListener('keydown', e => { if(e.key==='Enter') { sendAIMessage(aiInput.value); aiInput.value=''; } });
  }

  initChartTooltips();
}

// ─────────────────────────────────────────────────────────────────
// CHART TOOLTIPS
// ─────────────────────────────────────────────────────────────────
function initChartTooltips() {
  // Ensure a single shared tooltip element exists
  let tip = document.getElementById('fp-chart-tip');
  if (!tip) {
    tip = document.createElement('div');
    tip.id = 'fp-chart-tip';
    tip.className = 'fp-chart-tooltip';
    document.body.appendChild(tip);
  }

  const showTip = (html, e) => {
    tip.innerHTML = html;
    tip.classList.add('visible');
    moveTip(e);
  };
  const hideTip = () => tip.classList.remove('visible');
  const moveTip = (e) => {
    const offX = 14, offY = -10;
    let x = e.clientX + offX;
    let y = e.clientY + offY;
    // Clamp to viewport (approximate before paint)
    if (x + 200 > window.innerWidth) x = e.clientX - 200 - offX;
    if (y < 8) y = e.clientY + Math.abs(offY) + 8;
    tip.style.left = x + 'px';
    tip.style.top = y + 'px';
  };

  const today = new Date();

  // Sparkline hit circles (7-point weekly data for SEO; latency for monitors)
  $$('.fp-spark-hit').forEach(circle => {
    circle.addEventListener('mouseenter', e => {
      const idx = Math.max(0, +circle.dataset.idx);
      const total = Math.max(1, +circle.dataset.total);
      const color = escHtml(circle.dataset.color || '#2563EB');
      if (circle.dataset.type === 'latency') {
        const latency = +circle.dataset.score;
        const checksAgo = total - 1 - idx;
        const timeLabel = checksAgo === 0 ? 'Dernier check' : checksAgo === 1 ? 'Il y a 1 check' : `Il y a ${checksAgo} checks`;
        const valStr = latency === 0 ? '0ms (DOWN)' : `${latency}ms`;
        showTip(`
          <div class="fp-chart-tooltip-label">${escHtml(timeLabel)}</div>
          <div class="fp-chart-tooltip-value" style="color:${color}">${escHtml(valStr)}</div>
        `, e);
      } else {
        const safeScore = Math.max(0, Math.min(100, Math.round(+circle.dataset.score)));
        const weeksAgo = total - 1 - idx;
        const label = weeksAgo === 0 ? 'Cette semaine' : weeksAgo === 1 ? 'Semaine dernière' : `Il y a ${weeksAgo} sem.`;
        showTip(`
          <div class="fp-chart-tooltip-label">${escHtml(label)}</div>
          <div class="fp-chart-tooltip-value" style="color:${color}">${safeScore}<span>/100</span></div>
        `, e);
      }
    });
    circle.addEventListener('mousemove', moveTip);
    circle.addEventListener('mouseleave', hideTip);
  });

  // 30-point latency chart hit circles (monitor detail panel — dynamically rendered, use delegation)
  // Guard against duplicate bindings if initChartTooltips is called more than once
  if (!document._fpLatHitListenerBound) {
    document._fpLatHitListenerBound = true;
    let latHitActive = null;
    document.addEventListener('mousemove', e => {
      const circle = e.target.closest('.fp-lat-hit');
      if (circle) {
        const v = +circle.dataset.v;
        const idx = +circle.dataset.idx;
        const total = +circle.dataset.total;
        const color = escHtml(circle.dataset.color || '#2563EB');
        const checksAgo = total - 1 - idx;
        const timeLabel = checksAgo === 0 ? 'Dernier check' : `-${checksAgo} checks ago`;
        const valStr = v === 0 ? 'Timeout' : `${v}ms`;
        if (latHitActive !== circle) {
          latHitActive = circle;
          const svg = circle.closest('svg');
          if (svg) {
            svg.querySelectorAll('.fp-lat-marker').forEach(m => { m.style.display = 'none'; });
            const marker = svg.querySelector(`.fp-lat-marker[data-idx="${idx}"]`);
            if (marker) marker.style.display = 'block';
          }
        }
        showTip(`
          <div class="fp-chart-tooltip-label">${escHtml(timeLabel)}</div>
          <div class="fp-chart-tooltip-value" style="color:${color}">${escHtml(valStr)}</div>
        `, e);
      } else if (latHitActive) {
        latHitActive = null;
        hideTip();
        document.querySelectorAll('.fp-lat-marker').forEach(m => { m.style.display = 'none'; });
      }
    });
  }

  // 30-day trend chart hit circles — tooltip is now handled by the SVG-level mousemove handler below

  // Crosshair vertical line on 30-day trend chart
  $$('.fp-trend-chart-svg').forEach(svg => {
    const xhair = svg.querySelector('.fp-xhair-line');
    if (!xhair) return;
    svg.addEventListener('mousemove', e => {
      const rect = svg.getBoundingClientRect();
      const vbW = parseFloat(svg.dataset.padx) * 2 + parseFloat(svg.dataset.innerw);
      const x = ((e.clientX - rect.left) / rect.width) * vbW;
      const padX = parseFloat(svg.dataset.padx);
      const padY = parseFloat(svg.dataset.pady);
      const innerW = parseFloat(svg.dataset.innerw);
      const innerH = parseFloat(svg.dataset.innerh);
      const n = parseInt(svg.dataset.n);
      // Snap to nearest day index
      const rawIdx = (x - padX) / innerW * (n - 1);
      const idx = Math.max(0, Math.min(n - 1, Math.round(rawIdx)));
      const snappedX = padX + (idx / (n - 1)) * innerW;
      xhair.setAttribute('x1', snappedX);
      xhair.setAttribute('x2', snappedX);
      xhair.setAttribute('y1', padY);
      xhair.setAttribute('y2', padY + innerH);
      xhair.style.display = 'block';
      // Show dot highlights only at the hovered day index
      svg.querySelectorAll('.fp-trend-dot').forEach(dot => {
        dot.style.display = +dot.dataset.idx === idx ? 'block' : 'none';
      });
      // Show multi-site tooltip for the hovered day
      const hits = [...svg.querySelectorAll('.fp-trend-hit')].filter(c => +c.dataset.idx === idx);
      if (hits.length) {
        const daysAgo = n - 1 - idx;
        const d = new Date(today);
        d.setDate(d.getDate() - daysAgo);
        const dateStr = d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
        const rows = hits.map(h => {
          const safeScore = Math.max(0, Math.min(100, Math.round(+h.dataset.score)));
          return `<div style="display:flex;align-items:center;gap:6px;padding:2px 0">
            <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${escHtml(h.dataset.color)};flex-shrink:0"></span>
            <span style="font-size:10px;color:rgba(255,255,255,0.7);flex:1;max-width:110px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(h.dataset.site)}</span>
            <span style="font-size:11px;font-weight:700;color:${escHtml(h.dataset.color)}">${safeScore}</span>
          </div>`;
        }).join('');
        showTip(`
          <div class="fp-chart-tooltip-date" style="margin-bottom:5px">${escHtml(dateStr)}</div>
          ${rows}
        `, e);
      }
    });
    svg.addEventListener('mouseleave', () => {
      xhair.style.display = 'none';
      svg.querySelectorAll('.fp-trend-dot').forEach(dot => { dot.style.display = 'none'; });
      hideTip();
    });
  });

  // Calendar RDV event tooltips
  $$('.fp-cal-rdv').forEach(rdv => {
    rdv.addEventListener('mouseenter', e => {
      const id = rdv.dataset.calEventId;
      const ev = (STATE.calendarEvents||[]).find(ce => ce.id === id);
      if (!ev) return;
      const timeRange = (ev.startTime && ev.duration) ? formatTimeRange(ev.startTime, ev.duration) : '';
      const safeTimeRange = escHtml(timeRange);
      const dur = ev.duration ? (ev.duration >= 60 ? Math.floor(ev.duration/60)+'h'+(ev.duration%60?ev.duration%60+'min':'') : ev.duration+'min') : '';
      showTip(`
        <div class="fp-chart-tooltip-label" style="max-width:180px">${escHtml(ev.title)}</div>
        ${safeTimeRange ? `<div style="font-size:11px;color:var(--fp-accent);margin-top:3px;font-weight:600">🕐 ${safeTimeRange}</div>` : ''}
        ${ev.type ? `<div style="font-size:10px;color:var(--fp-text-muted);margin-top:2px">${escHtml(ev.type)}</div>` : ''}
        ${ev.site ? `<div style="font-size:10px;color:var(--fp-text-faint);margin-top:1px">${escHtml(ev.site.replace(/^https?:\/\//,''))}</div>` : ''}
        ${!timeRange && dur ? `<div style="font-size:10px;color:var(--fp-text-muted);margin-top:3px">⏱ ${dur}</div>` : ''}
        ${ev.notes ? `<div style="font-size:10px;color:var(--fp-text-muted);margin-top:4px;border-top:1px solid rgba(255,255,255,0.06);padding-top:4px;max-width:180px;white-space:pre-wrap;word-break:break-word">📝 ${escHtml(ev.notes.length>80?ev.notes.slice(0,80)+'…':ev.notes)}</div>` : ''}
        <div style="font-size:9px;color:var(--fp-text-faint);margin-top:4px;border-top:1px solid rgba(255,255,255,0.06);padding-top:4px">Cliquer pour modifier</div>
      `, e);
    });
    rdv.addEventListener('mousemove', moveTip);
    rdv.addEventListener('mouseleave', hideTip);
  });
}

// ─────────────────────────────────────────────────────────────────
// THEME
// ─────────────────────────────────────────────────────────────────
function applyTheme() {
  document.documentElement.dataset.theme = STATE.theme;
  if (STATE.themeManual) localStorage.setItem('fp-theme', STATE.theme);
  const sun = document.querySelector('.fp-icon-sun');
  const moon = document.querySelector('.fp-icon-moon');
  if (sun) sun.style.display = STATE.theme === 'dark' ? 'block' : 'none';
  if (moon) moon.style.display = STATE.theme === 'light' ? 'block' : 'none';
  // Update map style if visible
  if (STATE._gmap && STATE._gmapDark) {
    STATE._gmap.setOptions({ styles: STATE.theme === 'light' ? [] : STATE._gmapDark });
  }
}

function toggleTheme() {
  STATE.theme = STATE.theme === 'dark' ? 'light' : 'dark';
  STATE.themeManual = true;
  localStorage.setItem('fp-theme', STATE.theme);
  applyTheme();
  showToast('info', `Thème ${STATE.theme === 'dark' ? 'sombre' : 'clair'} activé`);
}

// ─────────────────────────────────────────────────────────────────
// ONBOARDING TOUR
// ─────────────────────────────────────────────────────────────────
const ONBOARDING_STEPS = [
  { title:'Bienvenue dans Flowpoint !', desc:'Votre centre de contrôle SEO local. Commençons par découvrir les fonctionnalités clés en 5 étapes rapides.' },
  { title:'Palette de commandes', desc:'Appuyez sur ⌘K (ou Ctrl+K) depuis n\'importe où pour accéder à toutes les sections, audits et actions en un instant.' },
  { title:'Lancez votre premier audit', desc:'Entrez une URL dans la section Audits et cliquez sur "Lancer". Vous obtiendrez un score SEO complet en secondes.' },
  { title:'Configurez un monitor', desc:'Les monitors surveillent la disponibilité de vos sites 24h/24. Créez-en un via le bouton + en bas à droite.' },
  { title:'Invitez votre équipe', desc:'Ajoutez vos collaborateurs dans la section Équipe. Ils pourront voir et gérer les données selon leur rôle.' },
];
let onboardingStep = 0;

function showOnboarding() {
  if (STATE.onboardingComplete) return;
  const el = $('#fp-onboarding');
  if (!el) return;
  el.removeAttribute('hidden');
  renderOnboarding();
}

function renderOnboarding() {
  const el = $('#fp-onboarding');
  if (!el) return;
  const step = ONBOARDING_STEPS[onboardingStep];
  el.innerHTML = `
    <div class="fp-onboarding-card">
      <div class="fp-onboarding-step">Étape ${onboardingStep+1} sur ${ONBOARDING_STEPS.length}</div>
      <div class="fp-onboarding-title">${step.title}</div>
      <div class="fp-onboarding-desc">${step.desc}</div>
      <div class="fp-onboarding-dots">
        ${ONBOARDING_STEPS.map((_,i)=>`<div class="fp-onboarding-dot${i===onboardingStep?' active':''}"></div>`).join('')}
      </div>
      <div class="fp-onboarding-actions">
        <button class="fp-btn fp-btn-ghost" id="onboarding-skip">Passer</button>
        <button class="fp-btn fp-btn-primary" id="onboarding-next">${onboardingStep<ONBOARDING_STEPS.length-1?'Suivant →':'Commencer !'}</button>
      </div>
    </div>
  `;
  $('#onboarding-skip').addEventListener('click', completeOnboarding);
  $('#onboarding-next').addEventListener('click', () => {
    if (onboardingStep < ONBOARDING_STEPS.length - 1) { onboardingStep++; renderOnboarding(); }
    else completeOnboarding();
  });
}

function completeOnboarding() {
  STATE.onboardingComplete = true;
  localStorage.setItem('fp-onboarded','1');
  const el = $('#fp-onboarding');
  if (el) el.setAttribute('hidden','');
  showToast('success','Bienvenue ! Votre dashboard est prêt 🎉');
}

// ─────────────────────────────────────────────────────────────────
// UTILITY
// ─────────────────────────────────────────────────────────────────
function escHtml(str) {
  if (!str) return '';
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// ─────────────────────────────────────────────────────────────────
// GLOBAL EVENT LISTENERS
// ─────────────────────────────────────────────────────────────────
function bindGlobalEvents() {
  // Nav items
  $$('.fp-nav-item, .fp-nav-ai').forEach(el => {
    el.addEventListener('click', () => {
      navigate(el.dataset.route);
      if (window.innerWidth <= 768) {
        $('#fp-sidebar')?.classList.remove('mobile-open');
        $('#fp-mobile-overlay')?.classList.remove('show');
        const h = $('#fp-hamburger');
        if (h) { h.classList.remove('open'); h.setAttribute('aria-expanded','false'); }
      }
    });
  });

  // Topbar status → monitors
  $('#topbar-status')?.addEventListener('click', () => navigate('monitors'));

  // Search trigger → command palette
  $('#fp-search-trigger')?.addEventListener('click', openCmdPalette);

  // Command palette backdrop
  $('#fp-cmd-palette')?.addEventListener('click', e => { if(e.target === $('#fp-cmd-palette')) closeCmdPalette(); });

  // Float panel close
  $('#fp-float-panel-close')?.addEventListener('click', closeFloatPanel);
  $('#fp-float-overlay')?.addEventListener('click', closeFloatPanel);

  // FAB
  $('#fp-fab')?.addEventListener('click', toggleFAB);
  $('#fp-fab-backdrop')?.addEventListener('click', closeFAB);

  // Mobile hamburger
  $('#fp-hamburger')?.addEventListener('click', () => {
    const sidebar = $('#fp-sidebar');
    const overlay = $('#fp-mobile-overlay');
    const hamburger = $('#fp-hamburger');
    const isOpen = sidebar.classList.toggle('mobile-open');
    overlay.classList.toggle('show', isOpen);
    hamburger.classList.toggle('open', isOpen);
    hamburger.setAttribute('aria-expanded', String(isOpen));
    overlay.setAttribute('aria-hidden', String(!isOpen));
  });
  $('#fp-mobile-overlay')?.addEventListener('click', () => {
    $('#fp-sidebar')?.classList.remove('mobile-open');
    $('#fp-mobile-overlay')?.classList.remove('show');
    const h = $('#fp-hamburger');
    if (h) { h.classList.remove('open'); h.setAttribute('aria-expanded','false'); }
    $('#fp-mobile-overlay')?.setAttribute('aria-hidden','true');
  });

  // Theme toggle
  $('#fp-theme-toggle')?.addEventListener('click', toggleTheme);

  // Shortcuts modal
  $('#fp-shortcuts-btn')?.addEventListener('click', () => {
    renderShortcutsModal();
    $('#fp-shortcuts-modal').removeAttribute('hidden');
  });
  $('#fp-shortcuts-close')?.addEventListener('click', () => $('#fp-shortcuts-modal').setAttribute('hidden',''));
  $('#fp-shortcuts-modal')?.addEventListener('click', e => { if(e.target === $('#fp-shortcuts-modal')) $('#fp-shortcuts-modal').setAttribute('hidden',''); });

  // Notifications
  $('#fp-notif-btn')?.addEventListener('click', e => {
    e.stopPropagation();
    const dd = $('#fp-notif-dropdown');
    if (dd.hasAttribute('hidden')) {
      renderNotifications();
      dd.removeAttribute('hidden');
    } else {
      dd.setAttribute('hidden','');
    }
  });

  // AI quick access in topbar
  $('#topbar-ai')?.addEventListener('click', () => {
    openFloatPanel('Assistant IA Flowpoint', renderAIPanelContent());
    setTimeout(() => {
      $$('.fp-ai-quick[data-ai-prompt]', $('#fp-float-panel-body')).forEach(btn => btn.addEventListener('click', async () => {
        await sendAIMessage(btn.dataset.aiPrompt);
        const msgs = $('#ai-panel-messages');
        if (msgs) { msgs.innerHTML = renderAIMessages(); msgs.scrollTop = msgs.scrollHeight; }
      }));
      const panelSend = $('#ai-panel-send');
      const panelInput = $('#ai-panel-input');
      panelSend?.addEventListener('click', async () => {
        const msg = panelInput?.value;
        if (!msg) return;
        panelInput.value = '';
        await sendAIMessage(msg);
        const msgs = $('#ai-panel-messages');
        if (msgs) { msgs.innerHTML = renderAIMessages(); msgs.scrollTop = msgs.scrollHeight; }
      });
      panelInput?.addEventListener('keydown', e => { if(e.key==='Enter') panelSend?.click(); });
    }, 80);
  });

  // Sidebar collapse toggle — guard against duplicate listeners from repeated bindEvents()
  if (!window.__fpSidebarBound) {
    window.__fpSidebarBound = true;
    $('#fp-sidebar-collapse')?.addEventListener('click', toggleSidebar);
  }

  // Logout
  $('#fp-logout-btn')?.addEventListener('click', () => { showToast('info','Déconnexion…'); setTimeout(()=>{ window.location.href='/login.html'; },1200); });

  // Messages button
  $('#fp-msg-btn')?.addEventListener('click', e => {
    e.stopPropagation();
    const dd = $('#fp-msg-dropdown');
    if (!dd) return;
    const isHidden = dd.hasAttribute('hidden');
    $('#fp-notif-dropdown')?.setAttribute('hidden','');
    if (isHidden) {
      dd.removeAttribute('hidden');
      dd.innerHTML = renderMsgDropdown();
      bindMsgPanel(dd);
    } else { dd.setAttribute('hidden',''); }
  });

  // Click outside → close context menu, notifications, FAB, messages
  document.addEventListener('click', e => {
    if (!e.target.closest('#fp-ctx-menu')) closeCtxMenu();
    if (!e.target.closest('#fp-notif-wrap')) $('#fp-notif-dropdown')?.setAttribute('hidden','');
    if (!e.target.closest('#fp-msg-wrap')) $('#fp-msg-dropdown')?.setAttribute('hidden','');
    if (!e.target.closest('#fp-fab-wrap') && STATE.fabOpen) closeFAB();
  });

  // Keyboard shortcuts
  document.addEventListener('keydown', e => {
    const tag = e.target.tagName;
    const inInput = tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT';

    // ⌘K / Ctrl+K → Command Palette
    if ((e.metaKey||e.ctrlKey) && e.key.toLowerCase()==='k') { e.preventDefault(); openCmdPalette(); return; }

    // Escape
    if (e.key==='Escape') {
      if (STATE.cmdOpen) { closeCmdPalette(); return; }
      if (STATE.activityPanelOpen) { closeActivityPanel(); return; }
      if (!$('#fp-float-panel').hasAttribute('hidden')) { closeFloatPanel(); return; }
      if (!$('#fp-shortcuts-modal').hasAttribute('hidden')) { $('#fp-shortcuts-modal').setAttribute('hidden',''); return; }
      if (STATE.fabOpen) { closeFAB(); return; }
      return;
    }

    if (inInput) return;

    // ? → shortcuts modal
    if (e.key==='?') { renderShortcutsModal(); $('#fp-shortcuts-modal').removeAttribute('hidden'); return; }

    // G + [key] navigation
    if (e.key.toLowerCase()==='g') {
      STATE.gPressed = true;
      clearTimeout(STATE.gTimer);
      STATE.gTimer = setTimeout(() => { STATE.gPressed = false; }, 1000);
      return;
    }
    if (STATE.gPressed) {
      const map = { o:'overview', a:'audits', m:'monitors', p:'missions', r:'reports', l:'local-seo', t:'team', b:'billing', s:'settings', i:'ai' };
      if (map[e.key.toLowerCase()]) { navigate(map[e.key.toLowerCase()]); STATE.gPressed = false; return; }
    }

    // J / K — row navigation in list views
    if (e.key.toLowerCase() === 'j' || e.key.toLowerCase() === 'k') {
      const rows = $$('.fp-mission-row, .fp-audit-row, .fp-monitor-row, .fp-monitor-card');
      if (rows.length === 0) return;
      if (STATE.selectedRowIndex === undefined) STATE.selectedRowIndex = -1;
      rows.forEach(r => r.classList.remove('fp-row-selected'));
      STATE.selectedRowIndex = e.key.toLowerCase() === 'j'
        ? Math.min(STATE.selectedRowIndex + 1, rows.length - 1)
        : Math.max(STATE.selectedRowIndex - 1, 0);
      const selected = rows[STATE.selectedRowIndex];
      if (selected) {
        selected.classList.add('fp-row-selected');
        selected.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
      return;
    }

    // E → export
    if (e.key.toLowerCase()==='e') { openFloatPanel('Exporter les données', renderExportPanel()); setupExportPanel(); return; }
  });

  // Hash routing
  window.addEventListener('hashchange', () => {
    const hash = window.location.hash.slice(1);
    if (hash && hash !== STATE.route) { STATE.route = hash; STATE.subRoute = null; render(); }
  });
}

// ─────────────────────────────────────────────────────────────────
// INIT
// ─────────────────────────────────────────────────────────────────
async function init() {
  // Apply theme immediately
  applyTheme();
  // Apply free modules (compact mode, focus mode, etc.)
  applyFreeModules();

  // Restore AI chat history for this session
  loadAIHistory();

  // Load data
  await loadData();

  // Missions rotation automatique toutes les 3 jours
  (() => {
    const lastKey = 'fp-mission-rotate-date';
    const last = parseInt(localStorage.getItem(lastKey) || '0');
    const now = Date.now();
    const THREE_DAYS = 3 * 24 * 3600 * 1000;
    if (now - last > THREE_DAYS && STATE.missions && STATE.missions.length > 1) {
      const todo = STATE.missions.filter(m => m.status === 'todo');
      for (let i = todo.length - 1; i > 0; i--) {
        const j = Math.floor(Math.abs(Math.sin(now + i) * 1000)) % (i + 1);
        const ti = STATE.missions.indexOf(todo[i]), tj = STATE.missions.indexOf(todo[j]);
        if (ti >= 0 && tj >= 0) { [STATE.missions[ti], STATE.missions[tj]] = [STATE.missions[tj], STATE.missions[ti]]; }
      }
      saveMissions();
      localStorage.setItem(lastKey, String(now));
    }
  })();

  // Update sidebar
  renderSidebarStatus();
  renderNotifications();

  // Init messages badge (uses channels system)
  { if (!STATE.channelMessages) STATE.channelMessages = JSON.parse(JSON.stringify(CHANNEL_MSGS_DEFAULT));
    const u = getMsgUnreadTotal();
    const b = $('#fp-msg-badge'); if (b) { u > 0 ? (b.removeAttribute('hidden'), b.textContent = u) : b.setAttribute('hidden', ''); } }

  // OS theme sync — listen for preference changes (only if no manual override)
  window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', e => {
    if (!STATE.themeManual) {
      STATE.theme = e.matches ? 'dark' : 'light';
      applyTheme();
    }
  });

  // Route from hash
  const hash = window.location.hash.slice(1);
  if (hash) STATE.route = hash;

  // Render
  render();

  // Bind global events
  bindGlobalEvents();

  // Shortcuts modal content
  renderShortcutsModal();

  // Onboarding
  showOnboarding();

  // Subscribe to Stripe billing SSE for real-time plan updates + activity events
  // NOTE: render() is intentionally NOT called from SSE handlers — data updates
  // are stored in STATE and a toast is shown; the user refreshes manually via
  // the "Actualiser" button. This prevents all unwanted automatic re-renders.
  (function subscribeBillingEvents() {
    if (PREVIEW_MODE) return;
    try {
      const es = new EventSource('/api/billing/events');
      es.onmessage = (e) => {
        try {
          const msg = JSON.parse(e.data);
          if (msg.type === 'plan_updated' && msg.plan && STATE.me) {
            const prev = STATE.me.plan;
            STATE.me.plan = msg.plan;
            if (prev !== msg.plan) {
              showToast('success', `Plan mis à jour : ${msg.plan} — actualisez pour voir les changements`);
            }
          } else if (msg.type === 'subscription_status' && STATE.me) {
            STATE.me.subscriptionStatus = msg.status;
            if (msg.status === 'past_due') showToast('warning','Paiement en retard — vérifiez votre facturation');
          } else if (msg.type === 'audit:auto-complete' && msg.audit) {
            const a = msg.audit;
            if (!STATE.audits.find(x => x.id === a.id)) {
              STATE.audits.unshift({ ...a, date: new Date().toISOString(), issues: 0, speed: 0, pinned: false });
              showToast('success', `Audit terminé — ${escHtml(a.url)} · Score : ${a.score}/100`);
            }
          } else if (msg.type === 'activity:new' && msg.event) {
            pushActivityEvent(msg.event);
          }
        } catch(err) {}
      };
      es.onerror = () => {
        es.close();
        setTimeout(subscribeBillingEvents, 60000);
      };
    } catch(e) {}
  })();

  // Bind activity panel interactions
  bindActivityPanel();
  // Show initial unread badge
  updateActivityBadge();

  // Make key functions globally accessible (for inline onclick handlers in rendered HTML)
  window.showToast = showToast;
  window.closeFloatPanel = closeFloatPanel;
  window.navigate = navigate;
  window.navigateSub = navigateSub;
  window.togglePushNotifications = togglePushNotifications;
  window.openFloatPanel = openFloatPanel;

  // Apply initial sidebar collapsed state (desktop only — on mobile the sidebar is a fixed drawer)
  if (STATE.sidebarCollapsed && window.innerWidth > 768) {
    $('#fp-sidebar')?.classList.add('collapsed');
    $('#fp-layout')?.classList.add('sidebar-collapsed');
  }

  // Update streak + score display
  const streakEl = $('#fp-streak-count');
  if (streakEl) streakEl.textContent = STATE.streak + 'j';
  const scoreEl = $('#fp-score-val');
  if (scoreEl) scoreEl.textContent = STATE.userScore;
}

// ─────────────────────────────────────────────────────────────────
// SIDEBAR TOGGLE
// ─────────────────────────────────────────────────────────────────
function toggleSidebar() {
  const isMobile = window.innerWidth <= 768;
  if (isMobile) {
    // On mobile the sidebar is a slide-over drawer; the collapse button just closes it
    const sidebar = $('#fp-sidebar');
    const overlay = $('#fp-mobile-overlay');
    sidebar?.classList.remove('mobile-open');
    overlay?.classList.remove('show');
    $('#fp-hamburger')?.classList.remove('open');
    return;
  }
  STATE.sidebarCollapsed = !STATE.sidebarCollapsed;
  const sidebar = $('#fp-sidebar');
  const layout  = $('#fp-layout');
  if (STATE.sidebarCollapsed) {
    sidebar?.classList.add('collapsed');
    layout?.classList.add('sidebar-collapsed');
    localStorage.setItem('fp-sidebar-collapsed', '1');
  } else {
    sidebar?.classList.remove('collapsed');
    layout?.classList.remove('sidebar-collapsed');
    localStorage.setItem('fp-sidebar-collapsed', '0');
  }
}

// ─────────────────────────────────────────────────────────────────
// SUB-PAGE CONTENT (for existing routes)
// ─────────────────────────────────────────────────────────────────
function renderSubPageContent(route, sub) {
  if (route === 'overview') {
    if (sub === 'insights') return renderOverviewInsights();
    if (sub === 'quick-wins') return renderOverviewQuickWins();
    if (sub === 'checklist') return renderOverviewChecklist();
  }
  if (route === 'missions') {
    if (STATE.missionView !== 'list') return null;
    if (sub === 'todo')       return renderMissionsFiltered('todo');
    if (sub === 'inprogress') return renderMissionsFiltered('inprogress');
    if (sub === 'done')       return renderMissionsFiltered('done');
    if (sub === 'ai')         return renderMissionsAI();
  }
  if (route === 'audits') {
    if (sub === 'analysis')    return renderAuditsAnalysis();
    if (sub === 'compare')     return renderAuditsCompare();
    if (sub === 'history')     return renderAuditsHistory();
    if (sub === 'opportunites') return renderAuditsOpportunites();
  }
  if (route === 'monitors') {
    if (sub === 'performance') return renderMonitorsPerformance();
    if (sub === 'incidents')   return renderMonitorsIncidents();
    if (sub === 'config')      return renderMonitorsConfig();
    if (sub === 'sla')         return renderMonitorsSLA();
  }
  if (route === 'local-seo') {
    if (sub === 'zones')         return renderLocalSEOZones();
    if (sub === 'competitors')   return renderLocalSEOCompetitors();
    if (sub === 'opportunities') return renderLocalSEOOpportunities();
    if (sub === 'gbp')           return renderLocalSEOGBP();
  }
  if (route === 'reports') {
    if (sub === 'history')   return renderReportsHistory();
    if (sub === 'templates') return renderReportsTemplates();
  }
  if (route === 'team') {
    if (sub === 'chat')        return renderTeamChat();
    if (sub === 'activity')    return renderTeamActivity();
    if (sub === 'files')       return renderTeamFiles();
    if (sub === 'performance') return renderTeamPerformance();
  }
  if (route === 'settings') {
    if (sub === 'alerts') return renderAlertRules();
    if (sub === 'api')    return renderSettingsAPI();
  }
  if (route === 'conversion') {
    if (sub === 'heatmap') return renderConversionHeatmap();
  }
  return null;
}

